from pathlib import Path
import json, uuid, hashlib

O = Path(__file__).parent
INPUT = json.loads((O / 'whole-thirteen-current532-DEEN-contracts-and-original-P-exact-intake.json').read_text())
BY = {r['wholeCurrentGoal']['id'][:8]: r for r in INPUT}
MATERIALS = []
AUTHOR_ROWS = []

def add(prefix, title, title_en, case_a, case_b, guard_de, guard_en, sources=()):
    g = BY[prefix]['wholeCurrentGoal']
    mid = str(uuid.uuid5(uuid.NAMESPACE_URL, 'skillpilot:economics:2026-10-10:local-stabilisation-two-real-cases:' + g['id']))
    criteria = []
    def render(case, language, solution=False):
        suffix = '' if language == 'de' else '_en'
        text = '## ' + case['name' + suffix] + '\n\n'
        if not solution:
            text += case['dossier' + suffix] + '\n\n'
            for n, q in enumerate(case['prompts' + suffix], 1):
                text += str(n) + '. ' + q + '\n'
        else:
            for n, q in enumerate(case['solutions' + suffix], 1):
                text += str(n) + '. ' + q + '\n\n'
        return text.rstrip()
    for letter, case in [('A', case_a), ('B', case_b)]:
        assert all(len(case[k]) == 3 for k in ('prompts', 'prompts_en', 'solutions', 'solutions_en', 'criteria', 'criteria_en'))
        for n in range(3):
            criteria.append({'id': letter.lower() + str(n + 1), 'points': 4,
                             'description': case['criteria'][n], 'descriptionEn': case['criteria_en'][n]})
    policy_de = ('Bewertung: 24 Punkte, bestanden ab 15. Die sechs Rasterzeilen haben jeweils 4 Punkte; ihre beschriebenen Teilpunkte werden auch bei unvollständigen Antworten vergeben. '
                 'Tragfähige andere Gewichtungen und Schlussurteile sind gleichwertig, wenn sie die Falldaten, Wirkungsmechanismen und Grenzen begründen. '
                 'Leistung zählt dort, wo sie tatsächlich erbracht wurde, auch außerhalb der vorgesehenen Teilfrage; derselbe Beitrag wird nur einmal bewertet. Es gibt keine Pflichtzahl an Stichwörtern oder fehlerfreien Einzelrechnungen. '
                 + guard_de + ' Eine schwache Einzelbegründung oder ein lokaler Rechenfehler allein löst diese Begrenzung nicht aus.')
    policy_en = ('Assessment: 24 points, pass at 15. Each of the six rubric rows has 4 points; the specified partial credit is available for incomplete answers. '
                 'Other defensible priorities and conclusions receive equal credit when justified with the case data, mechanisms and limits. '
                 'Credit evidence wherever it occurs, including another subquestion, but never twice. There is no quota of keywords or flawless calculations. '
                 + guard_en + ' One weak explanation or local calculation error alone does not trigger this limit.')
    task_de = ('# ' + title + '\n\nBearbeite die beiden eigenständigen Fälle mit den bereitgestellten Informationen. '
               'Zahlen und Verfahrensregeln sind ausdrücklich fiktive Unterrichtsannahmen, sofern ein datierter amtlicher Quellenteil sie nicht ausdrücklich als historischen Befund ausweist.\n\n'
               + render(case_a, 'de') + '\n\n' + render(case_b, 'de') + '\n\n' + policy_de)
    task_en = ('# ' + title_en + '\n\nAddress the two independent cases using the supplied information. '
               'Numbers and procedural rules are expressly fictional classroom assumptions unless a dated official source section explicitly identifies them as historical observations.\n\n'
               + render(case_a, 'en') + '\n\n' + render(case_b, 'en') + '\n\n' + policy_en)
    sol_de = render(case_a, 'de', True) + '\n\n' + render(case_b, 'de', True) + '\n\n' + policy_de
    sol_en = render(case_a, 'en', True) + '\n\n' + render(case_b, 'en', True) + '\n\n' + policy_en
    m = {'id': mid, 'title': title, 'titleEn': title_en,
         'description': 'Die lernende Person kann in zwei unterschiedlichen materialgestützten Fällen ' + g['title'] + ' selbstständig untersuchen und ein fachlich begründetes, bedingtes Urteil entwickeln.',
         'descriptionEn': 'The learner can independently investigate ' + g.get('titleEn', g['title']) + ' in two distinct material-based cases and develop a reasoned, conditional judgment.',
         'weight': 1, 'tags': [x for x in g['tags'] if x in ('GK', 'LK')] + ['Practice', 'Assessment'],
         'contains': [], 'requires': [g['id']], 'type': 'atomic', 'phase': g['dimensionTags']['phase'],
         'dimensionTags': {'framework': 'canonical-gymnasium-economics', 'demandLevel': 'AB3', 'phase': g['dimensionTags']['phase'], 'guidingIdeas': ['WW_WIRTSCHAFT', 'WW_POLITIK']},
         'extendedData': {'applicabilityFromRequires': True,
                          'authorCandidateDisposition': {'status': 'inert-draft-needs-independent-whole-material-and-course-review', 'reasonDe': 'Eigene neue vollständige Zwei-Fall-Aufgabe auf unverändertem ganzem Ziel-/P-Vertrag. Autorprüfungen ersetzen keine unabhängige Prüfung, Kurs-/Quellenfreigabe oder menschliche Freigabe.'}},
         'examData': {'reviewStatus': 'draft', 'coveredGoalIds': [g['id']], 'coveredStrands': [g.get('area', 'Wirtschaftswissenschaften')],
                      'demandLevels': ['AB1', 'AB2', 'AB3'], 'taskContent': task_de, 'taskContentEn': task_en,
                      'solutionContent': sol_de, 'solutionContentEn': sol_en,
                      'scoring': {'maxPoints': 24, 'passingPoints': 15, 'steps': criteria}}}
    MATERIALS.append(m)
    AUTHOR_ROWS.append({'materialId': mid, 'assessedCurrentGoalId': g['id'], 'wholeGoal': g,
                        'wholeOriginalPRecord': BY[prefix]['wholeCurrentOriginalPRecord'],
                        'sourceIds': list(sources), 'caseA': case_a, 'caseB': case_b,
                        'guardDe': guard_de, 'guardEn': guard_en,
                        'authorOnly': True, 'independentApproval': False})

add('6600f5f0', 'Flusswasser und Wohnungsknappheit: Eingriffe begründet abwägen',
    'River water and housing scarcity: judging interventions',
    dict(name='Fall A: Wer schützt den Fluss?', name_en='Case A: protecting a river',
         dossier='Drei Betriebe leiten Stoffe in einen Fluss. Anwohner tragen Reinigungskosten, die in den Produktpreisen nicht enthalten sind. Alle Stoffmengen sind messbar, aber jede jährliche Kontrolle kostet 6. Ohne neue Regel bleiben die Schäden voraussichtlich bestehen. Eine gleich strenge Mengenobergrenze kann je Betrieb 20 Einheiten vermeiden; die Vermeidungskosten dafür betragen 10, 30 und 60. Alternative: ein Preis pro eingeleiteter Einheit mit Messung und Sanktionen; die Reaktionen sind noch unbekannt. Die Unterrichtsregeln erlauben beide Instrumente. Ein Fonds erstattet nur nachgewiesene Anwohnerschäden aus allgemeinen Steuern, ohne die Einleitungskosten der Betriebe zu ändern.',
         dossier_en='Three firms discharge substances into a river. Residents bear cleanup costs missing from product prices. Quantities can be measured, but each annual inspection costs 6. Without a new rule the damage is expected to persist. An equally strict quantity limit can prevent 20 units per firm at abatement costs of 10, 30 and 60. Alternatively, discharge is charged per unit with measurement and penalties; responses are unknown. Both instruments are permitted by the classroom rules. A fund reimburses proven residents’ losses through general taxation without changing firms’ discharge costs.',
         prompts=['Erkläre das Marktproblem und vergleiche Obergrenze und Abgabe hinsichtlich Anreizen und erforderlicher Information.', 'Untersuche die Kontrollkosten und die unterschiedliche Kostenbelastung; vergleiche auch Fonds und Nicht-Eingreifen.', 'Empfiehl bedingt eine Regel. Nenne einen ernsthaften Einwand und eine Information, die dein Urteil verändern würde.'],
         prompts_en=['Explain the market problem and compare the limit with charging in terms of incentives and required information.', 'Examine inspection costs and uneven abatement costs; also compare the fund and non-intervention.', 'Recommend a rule conditionally, giving a serious objection and information that could change your judgment.'],
         solutions=['Externe Schäden werden nicht intern getragen: private Produktion kann gesellschaftlich zu belastend sein. Die Grenze sichert eine Menge bei Durchsetzung; die Abgabe macht Emissionen teuer und lässt unterschiedliche kostengünstige Reaktionen zu, garantiert ohne Reaktionswissen aber keine bestimmte Restmenge.', 'Kontrollen aller drei kosten 18 jährlich, zusätzlich zu Vermeidung und Verwaltung. Gleiche 20 vermeiden kostet zusammen 100 und belastet die Betriebe sehr verschieden. Der Fonds verteilt Schäden um, verändert aber allein nicht den Grenzanreiz zum Einleiten. Nicht-Eingreifen spart Verwaltung, lässt Schäden bestehen; die Schadenshöhe fehlt für eine Nettorechnung.', 'Eine Abgabe ist bei zuverlässiger Messung und flexibler Anpassung plausibel; bei einer zwingenden ökologischen Belastungsgrenze eher die durchgesetzte Obergrenze. Beide Urteile benötigen Kosten/Schadensvergleich, Umgehungs- und Vollzugsprüfung. Fehlende Schadensschwelle oder Reaktion auf Preise kann die Wahl ändern.'],
         solutions_en=['External losses are not internal costs, so private output can impose excessive social harm. A limit secures a quantity if enforced; a charge prices discharges and permits different low-cost responses, but without response information does not guarantee a particular remaining quantity.', 'Inspecting all three costs 18 annually, besides abatement and administration. Equal reductions of 20 cost 100 altogether and burden firms differently. Reimbursement redistributes harm but alone leaves the discharge incentive unchanged. Non-intervention saves administration but retains damage; missing damage valuation prevents a net-benefit calculation.', 'Charging is defensible with reliable measurement and flexible adjustment; an enforced limit may be preferable under a binding ecological ceiling. Either judgment must consider damage, costs, avoidance and enforcement. An unknown damage threshold or price response could change the choice.'],
         criteria=['A1: externes Marktproblem1, Mengenregelmechanismus1, Abgabenmechanismus1, Informationsunterschied1.', 'A2: Kontrolle18=1, Vermeidung100 und Ungleichheit1, Fondsanreiz1, Nicht-Eingreifen/fehlende Schadensbewertung1.', 'A3: begründete Wahl1, wirksame Vollzugsbedingung1, ernsthafter Gegengrund1, urteilsrelevante Information1.'],
         criteria_en=['A1: external market problem1, quantity mechanism1, charging mechanism1, information difference1.', 'A2: inspections18=1, abatement100 and inequality1, fund incentive1, non-intervention/missing damage valuation1.', 'A3: reasoned choice1, enforcement condition1, serious counterargument1, decision-relevant information1.']),
    dict(name='Fall B: Ein günstiger Preis genügt nicht', name_en='Case B: a low price alone is insufficient',
         dossier='In einer fiktiven Stadt liegt die markträumende Monatsmiete bei 800. Bei einer durchgesetzten Obergrenze von 600 werden 120 Wohnungen nachgefragt und 80 angeboten. Bereits vermietete Wohnungen behalten die Grenze; neue Bautätigkeit braucht zwei Jahre. Wohnberechtigungen sollen einkommensarme Haushalte bevorzugen, werden aber nur lückenhaft kontrolliert. Alternative: befristete gezielte Mietzuschüsse aus dem Stadthaushalt; kurzfristig kann das Angebot kaum wachsen. Keine Maßnahme, Zuschuss und Preisgrenze sind Unterrichtsoptionen, keine Aussage über heutiges Mietrecht.',
         dossier_en='In a fictional city the market-clearing monthly rent is 800. At an enforced ceiling of 600, 120 homes are demanded and 80 supplied. Existing tenancies retain the ceiling; new construction takes two years. Access permits aim to favour low-income households but checks are incomplete. Alternatively, temporary targeted rent support is financed from the city budget; supply hardly expands in the short run. Non-intervention, support and the ceiling are classroom options, not statements about current tenancy law.',
         prompts=['Analysiere Preis, Knappheit und tatsächlichen Zugang bei der Grenze.', 'Vergleiche Zuschuss und Grenze mit Nicht-Eingreifen: Verteilung, Finanzierung, Information und kurzfristige Nebenwirkungen.', 'Begründe eine Entscheidung für das kurzfristige Zugangsproblem und einen ergänzenden langfristigen Ansatz; benenne eine Grenze deines Urteils.'],
         prompts_en=['Analyse price, scarcity and actual access under the ceiling.', 'Compare support and the ceiling with non-intervention: distribution, funding, information and short-run side effects.', 'Justify a decision on short-run access plus a longer-run complementary approach, identifying a limit of your judgment.'],
         solutions=['Die Grenze liegt unter 800; Nachfrageüberschuss40. Die 80 erfolgreichen Mieter zahlen weniger, aber 40 Nachfrager erhalten im Modell keine Wohnung. Berechtigungskontrolle/Rationierung ist entscheidend; niedriger Preis allein beweist keinen Zugang für alle Armen.', 'Zuschüsse verbessern Zahlungsfähigkeit ausgewählter Haushalte, kosten Haushaltmittel und benötigen Bedürftigkeitsprüfung. Bei starrem Angebot können zusätzliche Zahlungsfähigkeit und Konkurrenz Mieten erhöhen. Die Grenze begünstigt erfolgreiche Bestandsmieter, kann Angebot/Qualität schwächen; Nicht-Eingreifen erhält Preisanreize, aber arme Haushalte können ausgeschlossen werden.', 'Gezielte Unterstützung mit verlässlicher Auswahl ist bedingt plausibel, ergänzend mittel- bis langfristig zusätzliche zugängliche Wohnungen. Auch eine begründete vorübergehende Grenze mit wirksamer Vergabe ist vertretbar. Budget, tatsächliche Angebotsreaktion und Verteilung dürfen nicht als bekannt vorausgesetzt werden.'],
         solutions_en=['The ceiling is below 800; excess demand is40. The 80 successful tenants pay less, but40 seekers obtain no dwelling in the model. Eligibility checks and rationing matter; a low price does not prove access for every poor household.', 'Support improves selected households’ purchasing ability, uses budget resources and needs eligibility checks. With rigid supply, increased purchasing power and competition may raise rents. The ceiling benefits successful incumbents but can weaken supply or quality; non-intervention retains price incentives but may exclude poorer households.', 'Targeted support with reliable selection is conditionally defensible, complemented by additional accessible housing over time. A temporary ceiling with effective allocation can also be justified. Budget, actual supply responses and distribution are not known facts.'],
         criteria=['B1: unter Gleichgewicht1, Überschuss40=1, Preis/Zugang unterscheiden1, Kontrolle/Rationierung1.', 'B2: Zuschussanreiz/Verteilung1, Haushalts-/Informationskosten1, Angebots-/Preiseffekt1, Grenze/Nicht-Eingreifen sachlich1.', 'B3: kurzfristige Wahl mit Grund1, Langfristmechanismus1, Grenze/Datenbedarf1, tragfähige Abwägung statt Automatismus1.'],
         criteria_en=['B1: below equilibrium1, shortage40=1, distinguish price/access1, checks/rationing1.', 'B2: support incentive/distribution1, budget/information costs1, supply/price effect1, ceiling/non-intervention1.', 'B3: reasoned short-run choice1, long-run mechanism1, limitation/data need1, defensible balance rather than automatism1.']),
    'Wenn in der gesamten Arbeit kein fallbezogener Interventionsmechanismus oder keinerlei begründete Abwägung seiner Kosten/Grenzen gegenüber einer Alternative gezeigt wird, sind höchstens 14 Punkte erreichbar.',
    'If the entire submission shows no case-specific intervention mechanism or no reasoned balance of its costs/limits against an alternative, the score is capped at14.')

add('d36664f5', 'Wachstum mit überprüfbaren ökologischen und sozialen Regeln', 'Growth under measurable environmental and social rules',
    dict(name='Fall A: Sauberer pro Einheit, schmutziger insgesamt?', name_en='Case A: cleaner per unit, more pollution overall?',
         dossier='Ein fiktiver Industriezweig produziert im Basisjahr 100 Einheiten mit je 10 Emissionseinheiten. Zwei Jahre später sind es 150 Produkte mit je 8 Emissionseinheiten. Die regionale Unterrichtsstrategie verlangt spätestens im Jahr5 höchstens 900 Gesamtemissionseinheiten bei verlässlicher Beschäftigung. Option R begrenzt die geprüfte jährliche Gesamtmenge und versteigert die Berechtigungen; Option T fördert nur die Technik je Produkteinheit. Beschäftigung und Haushaltseinnahmen beider Optionen sind noch unbekannt. Niedrige Einkommen könnten durch höhere Preise besonders betroffen sein.',
         dossier_en='A fictional industry produces100 units with10 emissions each in the base year. Two years later it makes150 products with8 emissions each. The regional classroom strategy requires total emissions no higher than900 by year5 together with dependable employment. Option R limits verified annual total emissions and auctions permits; option T only subsidises per-unit technology. Employment and revenue effects remain unknown. Higher prices may particularly affect low-income households.',
         prompts=['Berechne Gesamtbelastung und Intensitätsänderung und prüfe die Aussage, das Ziel sei bereits erreicht.', 'Entwirf für R eine messbare Regel mit Zeitraum, Kontrolle und Durchsetzung. Vergleiche ihren Anreiz mit T.', 'Wäge die ökologische Wirkung mit sozialen und langfristig wirtschaftlichen Folgen ab; begründe eine bedingte Ergänzung und nötige Information.'],
         prompts_en=['Calculate total pollution and the intensity change; assess whether the objective has already been met.', 'Design a measurable R rule with timeframe, monitoring and enforcement, comparing its incentive with T.', 'Balance environmental effects against social and longer-term economic consequences; justify a conditional complement and needed information.'],
         solutions=['Basis1000, später1200: Gesamtbelastung+20%; Intensität10→8 also−20%. 900 ist weder erreicht noch durch sinkende Intensität allein garantiert. Wachstum kann Effizienzgewinne überkompensieren.', 'Beispielsweise geprüfte Emissionsmenge pro Jahr mit bindendem Pfad zu900 bis Jahr5, unabhängiger Messung, Veröffentlichung und Sanktionen. R macht Gesamtbelastung knapp und schafft Vermeidungsanreize; T verbilligt effiziente Technik, sichert bei Mengenwachstum aber keine absolute Grenze.', 'R kann Innovation und langfristige Ressourcensicherheit stärken, aber Anpassungs-/Kontrollkosten, Preise und Jobs belasten. Zielgerichtete Rückverteilung von Erlösen oder Übergangsqualifizierung kann soziale Lasten mindern, ohne jede Emission zu verbilligen. Erlös-, Beschäftigungs- und Vermeidungsdaten sind nötig; andere begründete Prioritäten möglich.'],
         solutions_en=['Base total1000, later1200: pollution+20%; intensity10→8 is−20%. The900 limit is neither reached nor guaranteed by falling intensity alone. Output growth can outweigh efficiency gains.', 'For example, verified annual emissions with a binding path to900 by year5, independent measurement, public reporting and penalties. R makes total pollution scarce and encourages abatement; T lowers efficient-technology costs but does not ensure an absolute limit when production grows.', 'R can strengthen innovation and long-run resource security while imposing adjustment, inspection, price and employment costs. Targeted revenue redistribution or retraining can reduce social burdens without making every discharge cheaper. Revenue, employment and abatement evidence is needed; other reasoned priorities are valid.'],
         criteria=['A1: beide Summen1, Intensität−20%=1, Gesamteffekt+20%=1, absolute Zielprüfung1.', 'A2: Indikator/Zeitpfad1, Kontrolle/Durchsetzung1, R-Anreiz1, T-Grenze1.', 'A3: soziale Belastung1, langfristige Wirtschaftswirkung1, passende Ergänzung1, bedingtes Urteil/Information1.'],
         criteria_en=['A1: both totals1, intensity−20%=1, total+20%=1, absolute target check1.', 'A2: metric/time path1, monitoring/enforcement1, R incentive1, T limitation1.', 'A3: social burden1, long-run economic effect1, suitable complement1, conditional judgment/information1.']),
    dict(name='Fall B: Eine Busflotte über zehn Jahre', name_en='Case B: a ten-year bus fleet',
         dossier='Eine Gemeinde vergleicht zwei fiktive Zehnjahresangebote. A: Kauf40, Betrieb jährlich8, 60 Ressourcenpunkte insgesamt, 100 erreichbare Arbeitsplätze für einkommensarme Haushalte. B: Kauf70, Betrieb jährlich5, 45 Ressourcenpunkte insgesamt, 80 erreichbare Arbeitsplätze ohne Sozialtarif. Ein Sozialtarif bei B kostet jährlich1 zusätzlich und erhöht diesen Zugangsindikator auf120. Alle Beträge sind vergleichbare konstante Geldeinheiten; Zinsen und Restwerte werden im Unterrichtsmodell ignoriert. Die Ressourcenpunkte beziehen Produktion und Betrieb ein, erfassen aber nicht jede Umweltwirkung. Finanzierung erfolgt aus begrenzten Gemeindehaushalten, nicht kostenlos.',
         dossier_en='A municipality compares fictional ten-year offers. A: purchase40, annual operation8, total60 resource points,100 jobs accessible to low-income households. B: purchase70, annual operation5, total45 resource points,80 accessible jobs without a social fare. A social fare for B costs1 extra annually and raises that access measure to120. Amounts use comparable constant money units; interest and residual values are ignored in the classroom model. Resource points include manufacture and operation but not every environmental effect. Limited municipal budgets fund the options; finance is not free.',
         prompts=['Berechne die Zehnjahreskosten der drei Optionen und ordne ökologische, soziale und wirtschaftliche Indikatoren zu.', 'Formuliere eine überprüfbare Beschaffungs-/Zugangsregel für deine bevorzugte Option samt Kontrolle und Finanzierungsfrage.', 'Vergleiche Zielkonflikt und mögliche Zielharmonie, verteidige dein Urteil gegen eine andere Priorität und begrenze die Modellrechnung.'],
         prompts_en=['Calculate ten-year costs for the three options and classify environmental, social and economic indicators.', 'Specify a verifiable procurement/access rule for your preferred option, with monitoring and a funding question.', 'Compare trade-offs and possible synergies, defend your choice against another priority and limit the model calculation.'],
         solutions=['A120, B120, B mit Tarif130. B nutzt15 Ressourcenpunkte weniger, verliert ohne Tarif Zugang20; Tarif schafft Zugang120 bei10 Mehrkosten. Anfangsinvestition und Gesamtkosten sind verschieden; Zugänglichkeit ist ein begrenzter sozialer Indikator.', 'Eine mögliche Regel: über10Jahre höchstens45 Ressourcenpunkte, mindestens120 vergleichbar erreichbare Stellen mit kontrollierten Fahrt-/Tarifdaten, nachvollziehbarer Ressourcenerhebung und gesichertem jährlichem Tarifbudget. Bei knapper Investitionsfinanzierung ist A oder ein begründeter Übergang vertretbar; Finanzierung muss ausdrücklich geprüft werden.', 'B+Tarif verbindet ökologische Verbesserung und mehr Zugang, verlangt aber zusätzliche Mittel und höheren anfänglichen Kapitaleinsatz. A kann kurzfristig finanzierbarer sein. Diskontierung, unsichere Lebensdauer, weitere Ökofolgen und tatsächliche Fahrplannutzung fehlen; keine universelle Rangfolge aus den drei Zahlen.'],
         solutions_en=['A120, B120, B plus fare130. B saves15 resource points but loses access20 without the fare; the fare gives access120 for10 extra cost. Upfront and total costs differ; accessibility is a limited social measure.', 'One possible rule: no more than45 resource points over10years and at least120 comparably reachable jobs, verified route/fare data, transparent resource accounting and a secured annual fare budget. With tight investment finance, A or a justified transition is defensible; funding must be checked explicitly.', 'B plus fare combines environmental improvement with greater access, but needs extra money and greater upfront capital. A may be more affordable immediately. Discounting, lifetime uncertainty, other environmental effects and actual use are missing; the three numbers do not imply a universal ranking.'],
         criteria=['B1: drei Kosten1, Ökoindikator1, Zugangseffekt1, Anfang/Gesamt/Begrenzung1.', 'B2: operationalisierte Regel1, Zeitraum/Kontrolle1, Finanzierung1, begründete Wahl1.', 'B3: Konflikt1, mögliche Harmonie1, ernsthafte Gegenpriorität1, konkrete Modell-/Datenbegrenzung1.'],
         criteria_en=['B1: three costs1, environmental measure1, access effect1, upfront/total/limit1.', 'B2: operational rule1, period/monitoring1, funding1, reasoned choice1.', 'B3: trade-off1, possible synergy1, serious competing priority1, specific model/data limit1.']),
    'Wenn in der gesamten Arbeit keine überprüfbare ökologische Regel oder keinerlei fallbezogene Verbindung zu sozialen oder längerfristigen wirtschaftlichen Folgen gezeigt wird, sind höchstens14 Punkte erreichbar.',
    'If the entire submission contains no verifiable environmental rule or no case-specific connection to social or longer-run economic consequences, the score is capped at14.')

ECB24='https://www.ecb.europa.eu/press/pr/date/2024/html/ecb.mp240606~2148ecdb3c.en.html'
ECB25='https://www.ecb.europa.eu/press/pr/date/2025/html/ecb.mp250605~3b5f67d007.en.html'
add('0242e34e', 'Zwei historische EZB-Entscheidungen aus ihrem damaligen Wissen erklären', 'Explaining two historical ECB decisions using their contemporary information',
    dict(name='Fall A: Die Entscheidung vom 6. Juni 2024', name_en='Case A: the decision of6June2024',
         dossier='Datierte eigene Lesehilfe zur amtlichen Mitteilung vom6.6.2024 ('+ECB24+'): drei Leitzinsen wurden um25 Basispunkte gesenkt; Einlagezins3,75% ab12.6.2024. Seit September2023 war Inflation um mehr als2,5 Prozentpunkte gefallen. Lohn-/Binnenpreisdruck blieb hoch. Damalige Inflationsprojektion für2024/2025/2026:2,5/2,2/1,9%; Wachstumsprojektion0,9/1,4/1,6%. Der Rat hielt an2% mittelfristig fest, wollte die Restriktion angemessen dosieren und legte keinen weiteren Zinspfad fest. Dies sind damalige Befunde/Projektionen, keine heutigen Raten oder später bewiesenen Jahresergebnisse.',
         dossier_en='Dated original reading aid for the official6June2024 release ('+ECB24+'): all three key rates fell25 basis points; the deposit rate became3.75% on12June. Inflation had fallen by more than2.5 percentage points since September2023; wage/domestic pressure persisted. Contemporary2024/2025/2026 inflation projections were2.5/2.2/1.9%; growth0.9/1.4/1.6%. The Council retained2% over the medium term, adjusted restriction and committed to no future rate path. These are contemporary observations/projections, not current rates or established later outcomes.',
         prompts=['Unterscheide Entscheidung, Preisbefund und Projektion. Berechne den vorherigen Einlagezins und ordne den Schritt ein.', 'Erkläre die Zinssenkung anhand von Inflationsentwicklung, Transmission und realwirtschaftlicher Lage im Mandat.', 'Prüfe das Urteil „Senkung trotz2,5%-Projektion bedeutet Aufgabe der Preisstabilität“. Benenne Unsicherheit und eine Information für den nächsten Beschluss.'],
         prompts_en=['Distinguish the decision, inflation observation and projection. Calculate the previous deposit rate and classify the move.', 'Explain the cut through inflation, transmission and real activity within the mandate.', 'Assess “cutting despite a2.5% forecast abandons price stability”, identifying uncertainty and information for the next decision.'],
         solutions=['Vorher4,00%, Senkung0,25 Prozentpunkte=25bp, nicht25% des Zinssatzes. Gemeldeter Rückgang ist beobachtete Entwicklung; Jahresprojektionen sind Erwartungen verschiedener Horizonte; Datum der Geltung ist12.6.', 'Sinkender Inflationsdruck und schwache/erholende Aktivität erlauben weniger Restriktion, aber Lohn-/Binnenpreise erklären Vorsicht. Finanzierung und Nachfrage reagieren verzögert/unsicher; Schritt passt zu mittelfristigem Ziel statt mechanischer Gleichsetzung aktueller Rate und Sollwert.', 'Keine Zielaufgabe folgt: Jahr2026 war1,9 prognostiziert, mittelfristige Rückkehr und weiterhin hinreichende Restriktion blieben Maßstab. Löhne, Kernpreise, Kreditbedingungen oder neue reale Daten können den nächsten Schritt ändern; keine garantierte Senkungsserie oder Wachstumswirkung.'],
         solutions_en=['Previously4.00%; the reduction is0.25 percentage points=25bp, not25% of the rate. The reported decline is an observation; annual projections concern different future horizons; implementation is12June.', 'Lower inflation pressure and weak/recovering activity can permit less restriction, while wage/domestic pressure warrants caution. Funding and demand respond with lags and uncertainty; the move concerns the medium-term objective, not a mechanical current-rate rule.', 'Abandonment does not follow:2026 inflation was projected at1.9, and return to the target with sufficient restriction remained the criterion. Wages, underlying prices, credit conditions or new real data may alter the next move; neither continued cuts nor growth is guaranteed.'],
         criteria=['A1: vorher4%=1, bp/Prozentpunkte1, Befund/Projektion1, Datierung/Geltung1.', 'A2: Inflationsentwicklung1, reale Lage1, Transmission mit Bedingung1, mittelfristiges Mandat1.', 'A3: begründete Widerlegung1, fortbestehender Druck1, konkrete Unsicherheit/Daten1, kein festgelegter Pfad1.'],
         criteria_en=['A1: previous4%=1, bp/percentage points1, observation/forecast1, dating/implementation1.', 'A2: inflation development1, real activity1, conditional transmission1, medium-term mandate1.', 'A3: reasoned rebuttal1, remaining pressure1, uncertainty/data1, no committed path1.']),
    dict(name='Fall B: Die Entscheidung vom 5. Juni 2025', name_en='Case B: the decision of5June2025',
         dossier='Datierte eigene Lesehilfe zur amtlichen Mitteilung vom5.6.2025 ('+ECB25+'): Senkung aller drei Leitzinsen um25bp; Einlagezins2,00% ab11.6.2025. Inflation lag damals ungefähr beim2%-Ziel. Inflationsprojektionen2025/2026/2027:2,0/1,6/2,0%; reales Wachstum0,9/1,1/1,3%. Niedrigere Energieannahmen und stärkerer Euro drückten die Projektionen; Handelsunsicherheit belastete Investitionen/Exporte. Lohnwachstum war noch erhöht, aber rückläufig. Der Rat blieb datenabhängig, beschlussweise und ohne vorgegebenen Zinspfad. Alle Aussagen beziehen sich auf den damaligen Informationsstand.',
         dossier_en='Original dated aid for the official5June2025 release ('+ECB25+'): all three key rates fell25bp; the deposit rate became2.00% on11June. Inflation was then around the2% target.2025/2026/2027 projections were2.0/1.6/2.0% inflation and0.9/1.1/1.3% real growth. Lower energy assumptions and a stronger euro reduced projections; trade uncertainty weighed on investment/exports. Wage growth remained elevated but slowed. Decisions remained data-dependent, meeting by meeting, with no predetermined rate path. Everything refers to that contemporary information set.',
         prompts=['Rekonstruiere den Zinsschritt und trenne die damaligen realen Hinweise von projizierten Werten.', 'Verbinde den Beschluss mit Preisstabilität, Transmission und realwirtschaftlicher Unsicherheit. Vergleiche die Entscheidungsgründe mit2024.', 'Beurteile die Aussage „Bei2% Inflation muss die EZB nichts ändern und die Senkung garantiert Wachstum“. Welche neue Entwicklung würde deine Einordnung revidieren?'],
         prompts_en=['Reconstruct the rate move and separate contemporary real signals from projections.', 'Connect the decision to price stability, transmission and real uncertainty; compare its reasons with2024.', 'Assess “at2% inflation the ECB must do nothing and the cut guarantees growth”. What new development would revise your interpretation?'],
         solutions=['Vorher2,25%, dann2,00%:−0,25 Prozentpunkte, ab11.6. Handelsunsicherheit/Lohntrend sind damalige Hinweise;0,9/1,1/1,3 und künftige Inflationswerte sind Prognosen, keine rückblickend bestätigte Reihe.', 'Mittelfristige Aussicht und Transmission zählen neben dem aktuellen Zielnähe-Befund. Geringere Energieannahmen/Euro und schwache Perspektive erlauben Anpassung; geringere Zinsen können Finanzierung/Nachfrage stützen, aber Unsicherheit kann Investitionen bremsen.2024 reduzierte man noch deutliche Restriktion bei stärkerem Preisüberhang;2025 lag Inflation näher am Ziel, Unsicherheit blieb.', 'Ein einzelner aktueller Wert schreibt keinen Automatismus vor, auch Unterschreiten der mittelfristigen Zielaussicht ist relevant. Ein Kreditzins-/Nachfragekanal ist keine Wachstumsgarantie. Neue Lohn-/Energie-, Kredit- oder Handelsdaten könnten eine Pause oder andere Reaktion tragen; andere bedingt begründete Bewertung ist zulässig.'],
         solutions_en=['Previously2.25%, then2.00%:−0.25 percentage points from11June. Trade uncertainty and wage trends are contemporary indications;0.9/1.1/1.3 and future inflation are forecasts, not a confirmed retrospective sequence.', 'Medium-term prospects and transmission matter alongside current target proximity. Energy/euro assumptions and weak prospects allow adjustment; cheaper finance can support demand, but uncertainty may restrain investment.2024 moderated substantial restriction with greater price pressure;2025 inflation was nearer target, with uncertainty remaining.', 'One current rate does not impose an automatic rule; a medium-term undershoot also matters. A credit/demand channel does not guarantee growth. New wage, energy, lending or trade data could support a pause or another response; different conditional assessments receive credit.'],
         criteria=['B1:2,25→2,00=1, bp/Geltung1, Projektionen1, damalige reale Hinweise1.', 'B2: Mandatsbezug1, Preis-/Wechselkursannahmen1, reales/Transmission1, nachvollziehbarer Vergleich2024=1.', 'B3: aktueller Wert kein Automatismus1, Wachstum nicht garantiert1, konkrete Revision1, begründetes bedingtes Urteil1.'],
         criteria_en=['B1:2.25→2.00=1, bp/effect date1, forecasts1, contemporary real signals1.', 'B2: mandate1, price/exchange assumptions1, real/transmission1, reasoned2024comparison1.', 'B3: no current-value automatism1, no growth guarantee1, specific revision1, conditional judgment1.']),
    'Wenn die gesamte Arbeit keine reale datierte Entscheidung anhand ihres damaligen Preis-/Realbefunds mit dem mittelfristigen Mandat verknüpft, sondern nur Zinswerte oder allgemeine Slogans wiedergibt, sind höchstens14 Punkte erreichbar.',
    'If the entire submission connects no actual dated decision, contemporary price/real evidence and medium-term mandate, merely repeating rates or slogans, the score is capped at14.',
    ['ecb2024', 'ecb2025'])

add('79d244e0', 'Bankenkrise und asymmetrischer Schock in einer Währungsunion', 'Bank distress and asymmetric shocks in a monetary union',
    dict(name='Fall A: Banken und Staat verstärken ihre Risiken', name_en='Case A: banks and government amplify each other’s risks',
         dossier='Fiktiver Euro-Mitgliedstaat R: Banken halten viele heimische Staatsanleihen. Deren Marktwert sinkt; Bankkapital wird schwächer, Kredite an Betriebe werden eingeschränkt. Eine staatliche Rettung könnte Verluste übernehmen, würde aber die Staatsschuld erhöhen. Neue Zweifel an der Zahlungsfähigkeit des Staates könnten Anleihepreise weiter drücken. Eigene amtliche Lesehilfe: gemeinsame Aufsicht und ein Mechanismus zur Abwicklung scheiternder Banken sind unterschiedliche Bausteine der europäischen Bankenunion (Europäische Kommission, Seite aktualisiert 17.7.2026: https://finance.ec.europa.eu/banking/banking-union/what-banking-union_en). Im Unterrichtsvorschlag S kontrolliert gemeinsame Aufsicht die Risikokonzentration vor einer Krise. Im Vorschlag A werden Verluste nach vorab geregelter Rangfolge zunächst Eigentümern und geeigneten Gläubigern zugeordnet, mit einem begrenzten finanzierten Abwicklungsfonds. Diese konkrete Rangfolge ist Modellannahme, keine Darstellung einzelner geltender Abwicklungsnormen.',
         dossier_en='Fictional euro member R: banks hold much domestic sovereign debt. Its market value falls, bank capital weakens and business lending contracts. A government rescue could absorb losses but increase public debt; doubts about the sovereign could further reduce bond prices. Original official-source aid: common supervision and resolution of failing banks are distinct banking-union components (European Commission, updated17July2026: https://finance.ec.europa.eu/banking/banking-union/what-banking-union_en). Classroom proposal S monitors risk concentrations before a crisis. Proposal A allocates losses initially to owners and eligible creditors under a pre-agreed order, with a limited funded resolution pool. This precise order is a model assumption, not an account of individual current legal provisions.',
         prompts=['Erkläre den Rückkopplungskreis und mögliche realwirtschaftliche Folgen in der Währungsunion.', 'Unterscheide Prävention durch S von Krisenbehandlung durch A. Prüfe Finanzierung, Haftung und mögliche Fehlanreize.', 'Empfiehl eine Kombination oder Alternative unter Bedingungen; benenne Verteilungs-/Umsetzungsgrenzen und eine urteilsrelevante Information.'],
         prompts_en=['Explain the feedback loop and possible real effects within the monetary union.', 'Distinguish prevention through S from crisis management through A; examine funding, liability and incentives.', 'Recommend a combination or alternative conditionally, identifying distribution/implementation limits and needed information.'],
         solutions=['Anleiheverlust schwächt Banken; staatliche Rettung schwächt Staatsfinanzen, neue Ausfallbefürchtung drückt die Anleihen erneut und trifft Banken. Kreditrückgang kann Investitionen/Jobs mindern und Steuereinnahmen senken. Gemeinsame Geldpolitik beseitigt nationale Bilanzverluste nicht automatisch; Ansteckung und unterschiedliche Finanzierung beeinträchtigen Transmission.', 'S kann über Risikokonzentration/Prüfung vorbeugen, wickelt aber akute Verluste nicht selbst ab. A ordnet Verluste und erhält wichtige Funktionen, benötigt glaubwürdige Vorfinanzierung und operative Verfahren. Haftung der Risikoträger begrenzt Rettungserwartung; blinde Vergemeinschaftung könnte Risikoanreize setzen, strenge Verlustzuordnung kann ihrerseits Panik/Ansteckung fördern.', 'S plus klar finanzierter A kann den Kreis schwächen, ist aber keine verlustfreie Garantie. Geschützte kritische Zahlungsfunktionen, Transparenz und Haftungsgrenzen sind plausible Bedingungen. Fondsgröße, tatsächliche Anleihebestände, grenzüberschreitende Forderungen und Umsetzungszeit fehlen; andere begründete Gewichtungen sind vertretbar.'],
         solutions_en=['Bond losses weaken banks; rescue weakens government finances, renewed default fears lower bonds again and hit banks. Reduced lending can depress investment/jobs and tax revenue. Common monetary policy does not erase national balance-sheet losses; contagion and uneven funding impair transmission.', 'S can prevent concentrations through monitoring but does not itself resolve existing losses. A allocates losses and preserves important functions, requiring credible pre-funding and operational procedures. Risk-bearer liability limits bailout expectations; unconditional pooling may encourage risk, while rigid loss allocation can trigger panic or contagion.', 'S plus a clearly financed A may weaken the loop without guaranteeing no loss. Critical payment functions, transparency and liability limits are defensible conditions. Fund size, actual exposures, cross-border claims and implementation time are missing; other reasoned priorities are valid.'],
         criteria=['A1: beide Rückkopplungsrichtungen2, reale Kredit-/Beschäftigungsfolge1, gemeinsame Geldpolitik/nationale Risiken1.', 'A2: S/A funktional unterscheiden1, Haftung1, Finanzierung1, Fehlanreiz/Gegenrisiko1.', 'A3: mechanistisch begründete Entscheidung1, Umsetzungsbedingung1, Verteilung/Gegengrund1, konkrete Information1.'],
         criteria_en=['A1: both feedback directions2, real lending/jobs effect1, common policy/national risk1.', 'A2: distinct S/A functions1, liability1, funding1, incentive/counter-risk1.', 'A3: mechanistic choice1, implementation condition1, distribution/counterargument1, information1.']),
    dict(name='Fall B: Ein Zins, zwei unterschiedliche Lagen', name_en='Case B: one rate, two different economies',
         dossier='Die fiktiven Euro-Länder R und S haben dieselbe gemeinsame Geldpolitik. In R bricht eine wichtige Exportnachfrage weg, Arbeitslosigkeit steigt und Staatseinnahmen fallen. S hat hohe Auslastung und zunehmenden Preisdruck. R kann keine eigene Euro-Leitzinssenkung oder Abwertung einer eigenen Währung beschließen. Zwei ausdrücklich hypothetische Reformoptionen: national aufgebaute Rücklagen, aus denen R in der Krise gezielt Einkommen stützt; oder ein gemeinsamer Fonds mit vorherigen Beiträgen und überprüfbaren Auszahlungen nur bei einem unerwarteten schweren Schock. Dauerhafte Transfers ohne Bedingungen sind eine dritte Diskussionsposition. Historische Quelle zum institutionellen Grundproblem: EZB, 27.11.2014, https://www.ecb.europa.eu/press/key/date/2014/html/sp141127_1.en.html; die drei Fondsvorschläge sind keine Behauptung über heute beschlossenes EU-Recht.',
         dossier_en='Fictional euro countries R and S share monetary policy. R loses important export demand, unemployment rises and revenue falls; S has high utilisation and rising price pressure. R cannot individually cut the euro policy rate or devalue a separate currency. Hypothetical reforms: national buffers accumulated beforehand, used by R for targeted income support; or a common pool with prior contributions and verifiable payments only after an unexpected severe shock. Unconditional permanent transfers are a third position. Historical source for the institutional problem: ECB,27November2014, https://www.ecb.europa.eu/press/key/date/2014/html/sp141127_1.en.html; these proposals do not describe adopted current EU law.',
         prompts=['Erkläre, weshalb ein gemeinsamer Zinsschritt nicht beide Probleme gleichzeitig passend lösen muss.', 'Vergleiche nationale Rücklagen und bedingten gemeinsamen Fonds hinsichtlich Stabilisierung, Finanzierbarkeit, Risikoteilung und Anreizen.', 'Begründe eine Reformbewertung mit ernsthafter Gegenposition. Nenne institutionelle und überprüfbare Umsetzungsbedingungen.'],
         prompts_en=['Explain why a common rate move need not fit both problems at once.', 'Compare national buffers and a conditional pool on stabilisation, financing, risk-sharing and incentives.', 'Judge a reform against a serious competing position, identifying institutional and verifiable implementation conditions.'],
         solutions=['Eine expansive gemeinsame Reaktion könnte R helfen, S aber zusätzlichen Preisdruck bringen. Ein restriktiver Schritt trifft R ungünstig. Asymmetrische reale/finanzielle Lagen bei gemeinsamer Geldpolitik erzeugen Anpassungsbedarf über andere Kanäle; nationale Fiskal- und Strukturmaßnahmen sind nicht eigenständige Geldpolitik.', 'Rücklagen ermöglichen schnelle nationale Hilfe, setzen vorherige Mittel voraus und teilen extreme Risiken wenig. Gemeinsame Beiträge können asymmetrische Schocks glätten, benötigen aber Finanzierung, belastbare Schockmessung und glaubwürdige Bedingungen. Unbedingte Dauermittel können Solidarität stärken, aber Zuständigkeit, Beitragsgerechtigkeit und Vorsorgeanreize sind Streitpunkte.', 'Ein begrenzter kontrollierter Fonds neben nationaler Vorsorge ist vertretbar; stärkere nationale Eigenverantwortung oder umfassendere Solidarität ebenfalls bei sachlichen Gründen. Zuständigkeit, demokratische Legitimation, Auslösekriterien, Obergrenzen, Prüfung und verlässliche Beiträge sind entscheidend. Weder gleiche Lage aller Länder noch kostenloses Haftungsversprechen annehmen.'],
         solutions_en=['Common easing might support R but add inflation pressure in S; tightening would hurt R. Asymmetric real/financial conditions under common policy require other adjustment channels; national fiscal or structural measures are not separate monetary policy.', 'Buffers enable rapid national support but require prior resources and share little extreme risk. Common contributions can smooth asymmetric shocks, but need finance, credible shock measurement and conditions. Unconditional permanent funds may support solidarity but raise authority, contribution fairness and precaution-incentive disputes.', 'A limited audited pool alongside national buffers is defensible, as are greater national responsibility or broader solidarity with substantive reasons. Authority, democratic legitimacy, trigger criteria, limits, checks and dependable contributions matter. Neither identical conditions nor cost-free liability should be assumed.'],
         criteria=['B1: asymmetrische Lage1, gemeinsame Zinswirkung1, fehlender eigener Wechselkurs/Zins1, anderer Anpassungskanal1.', 'B2: nationale Stabilisierung/Grenze1, gemeinsame Risikoteilung1, Finanzierung1, Anreize1.', 'B3: begründetes Reformurteil1, Gegenposition1, institutionelle Zuständigkeit1, überprüfbare Bedingung1.'],
         criteria_en=['B1: asymmetric conditions1, common-rate effects1, no national rate/exchange rate1, other channel1.', 'B2: national stabilisation/limit1, shared risk1, finance1, incentives1.', 'B3: reasoned reform choice1, competing position1, authority1, verifiable condition1.']),
    'Wenn in der gesamten Arbeit die Rückkopplung beziehungsweise das asymmetrische Problem ohne gemeinsamen monetären Rahmen erklärt wird oder keinerlei Reformmechanismus mit Haftungs-/Finanzierungs- oder Anreizgrenze begründet wird, sind höchstens14 Punkte erreichbar.',
    'If the whole submission explains feedback/asymmetry without the shared monetary framework, or justifies no reform mechanism with a liability/funding or incentive limitation, the score is capped at14.',
    ['bankingunion', 'ewuhistorical2014'])

add('bc3f895f', 'Ölschock, Nachfrage und Kredit: Modelle passend anwenden', 'Oil, demand and credit shocks: using suitable models',
    dict(name='Fall A: Historischer Auslöser, ausdrücklich fiktive Modelle', name_en='Case A: a historical trigger with explicitly fictional models',
         dossier='Historischer amtlicher Quellenhinweis: Federal Reserve History beschreibt ein Öl-Embargo arabischer Produzenten gegen die USA ab19.10.1973 und Produktionskürzungen mit Preis-/Wachstumsdruck; https://www.federalreservehistory.org/essays/oil-shock-of-1973-74. Dies ist ein historischer Angebots-/Kostenauslöser, nicht die ganze Erklärung aller damaligen Konjunkturfolgen. Für einen Unterrichtsvergleich werden zwei unabhängige fiktive Modelle vorgegeben, keine gemessenen Daten von1973. D: geschlossene Wirtschaft ohne Steuern, feste Preise und freie Kapazität; C=20+0,8Y, I=20, G=20, Y=C+I+G. Verunsicherung senkt im D-Szenario I auf10. S: bei unveränderter gewünschter Nachfrage sinkt durch Energieknappheit die mögliche Produktion von300 auf270; der Kosten-/Preisindex wird im Szenario von100 auf108 gesetzt. S-Werte sind gesetzte Modellannahmen, keine Ableitung aus D.',
         dossier_en='Official historical-source aid: Federal Reserve History describes an Arab-producer oil embargo against the US from19October1973 and output cuts with price/growth pressure; https://www.federalreservehistory.org/essays/oil-shock-of-1973-74. This is a historical supply/cost trigger, not the entire explanation of every contemporary cycle effect. Two separate fictional classroom models follow, not measured1973 data. D: closed economy, no taxes, fixed prices and spare capacity; C=20+0.8Y, I=20, G=20, Y=C+I+G. Uncertainty reduces I to10 in D. S: desired demand is unchanged but energy scarcity cuts possible output300→270; the scenario sets the cost/price index100→108. S values are assumptions, not derivations from D.',
         prompts=['Ordne den historischen Auslöser ein. Berechne in D Ausgangs- und Folgegleichgewicht und erkläre die Verstärkung.', 'Wende S an und vergleiche Annahmen und Preis-/Mengenerklärung mit D. Was darfst du aus keinem der Modelle über1973 behaupten?', 'Prüfe für einen tatsächlichen Öl-/Nachfrageschock eine bedingte Modellwahl und benenne zwei trennende Beobachtungen.'],
         prompts_en=['Identify the historical trigger. Calculate initial and later D equilibria and explain amplification.', 'Apply S and compare its assumptions and price/quantity explanation with D. What may neither model establish about1973?', 'Choose a model conditionally for an actual oil/demand shock and identify two discriminating observations.'],
         solutions=['Oktober1973 ist der zeitgebundene Angebots-/Kostenauslöser. D:0,2Y=60, Y=300; nach I=10:0,2Y=50, Y=250, ΔY=−50 bei ΔI=−10, Multiplikator5. Weniger Investition senkt Einkommen/Konsum und weitere Nachfrage bei gegebenen Annahmen.', 'S setzt Produktionsverlust30 und Preisindexanstieg8%; Energieengpass begrenzt Angebot trotz gleichbleibender Nachfrage. D erklärt Nachfrageverlust bei konstanten Preisen, kann dessen inflationäre Angebotsfolge nicht allein abbilden. Weder300/270/250 noch8% sind historische Messwerte oder vollständige1973-Kausalschätzungen.', 'Bei ungenutzter Kapazität und nachweisbarem Auftragsverlust D; bei Engpass/Kostensteigerung S; bei beidem beide Kanäle gesondert modellieren. Energielieferungen/Kosten sowie Aufträge/Auslastung und zeitliche/branchenspezifische Preisentwicklung helfen trennen. Eine Rangfolge ohne diese Daten bleibt bedingt.'],
         solutions_en=['October1973 is a dated supply/cost trigger. D:0.2Y=60 gives300; with I=10,0.2Y=50 gives250; ΔY=−50 for ΔI=−10, multiplier5. Lower investment reduces income, consumption and further demand under the assumptions.', 'S sets output loss30 and price-index rise8%; energy constrains supply despite unchanged demand. D describes demand contraction at fixed prices and alone cannot capture inflationary supply effects. None of300/270/250 or8% is a historical observation or a full1973 causal estimate.', 'Use D conditionally with spare capacity and observed order decline; S with bottlenecks/cost rises; separate channels when both operate. Energy deliveries/costs, orders/utilisation and timed sectoral prices discriminate. Without those data, any ranking remains conditional.'],
         criteria=['A1: datierter Auslöser1, Y300/250=1, Multiplikator5=1, Einkommens-/Konsumkette1.', 'A2: S-Menge/Preis1, Nachfrage-/Angebotsvergleich1, Annahmen1, Fiktion/Historie getrennt1.', 'A3: bedingte Auswahl1, Mischfallgrenze1, erste trennende Beobachtung1, zweite mit fachlicher Funktion1.'],
         criteria_en=['A1: dated trigger1, Y300/250=1, multiplier5=1, income/consumption chain1.', 'A2: S quantity/price1, demand/supply comparison1, assumptions1, fiction/history1.', 'A3: conditional choice1, mixed-case limit1, first discriminator1, second with function1.']),
    dict(name='Fall B: Energiemangel trifft Kreditpläne', name_en='Case B: energy scarcity meets credit plans',
         dossier='In einer anderen fiktiven Wirtschaft fehlen Energievorprodukte; Produktionskapazität und Kosten werden unsicher. Gleichzeitig sinken Konsumaufträge aus Verunsicherung. Ein Kreditmodell setzt geplante Investitionen I=40−5r, mit r als Kreditzins in Prozentpunkten. Neue Kreditangebote steigen von r=2 auf r=4; bei allen bereits finanzierten Projekten ist der Zins bis nächstes Jahr fest. Ein Nachfragemodell würde bei festen Preisen und freier Kapazität aus ΔI einen Multiplikator3 ableiten. Kein Modell enthält bisher Energieknappheit oder verzögerte Vertragsumstellung.',
         dossier_en='In another fictional economy, energy inputs are scarce and capacity/costs uncertain; consumer orders also fall through uncertainty. A credit model sets planned investment I=40−5r with r in percentage points. New offers rise from r=2 to4; already financed projects have fixed rates until next year. A demand model assumes fixed prices and spare capacity and would multiply ΔI by3. Neither model currently includes energy scarcity or delayed repricing.',
         prompts=['Berechne die geplante Investitionsänderung für neue Angebote und den rein bedingten Nachfrageeffekt. Trenne ihn von bereits finanzierten Projekten.', 'Erkläre getrennt Energie-, Nachfrage- und Kreditkanal und mindestens eine verletzte Annahme jedes pauschalen Ein-Modell-Urteils.', 'Entwirf eine kleine begründete Modellerweiterung und einen prüfbaren Beobachtungsvorschlag; gib eine vorsichtige Gesamtdiagnose.'],
         prompts_en=['Calculate planned investment for new offers and the conditional demand effect, distinguishing already financed projects.', 'Separate energy, demand and credit channels, identifying violated assumptions in sweeping single-model claims.', 'Propose a small justified model extension and testable observation, then give a cautious overall diagnosis.'],
         solutions=['I30→20, ΔI=−10; mit Faktor3 wäre ΔY=−30 nur bei den Nachfrageannahmen. Fest finanzierte Projekte werden nicht sofort mechanisch umgestellt; tatsächliche Umsetzung/Anteil neuer Kredite fehlt.', 'Energie kann Kosten/Preis erhöhen und Kapazität begrenzen; Unsicherheit senkt Konsum; höhere neue Kreditkosten drücken geplante Investition. Nachfragemodell ignoriert variable Preise/Knappheit, Kreditmodell ignoriert feste Altverträge und Erwartungen. Gleiche fallende Produktion beweist keine einzige Ursache und keine sichere Preisrichtung.', 'Ergänze explizit eine Energiekapazitätsgrenze und getrennte Anteile neuer/fester Kredite, oder eine zeitabhängige Konsumreaktion. Prüfe etwa Aufträge, Energieverfügbarkeit, Kreditneuverträge und Auslastung in zeitlicher Folge. Gemischter Gegenwind ist plausibel, Stärke/Nettoinflation bleiben offen.'],
         solutions_en=['I30→20, ΔI=−10; factor3 gives ΔY=−30 only under the demand assumptions. Fixed-funded projects do not instantly reprice; actual implementation and the share of new credit are unknown.', 'Energy may raise costs/prices and constrain capacity; uncertainty reduces consumption; higher new borrowing costs lower planned investment. The demand model omits changing prices/scarcity, the credit model fixed contracts and expectations. Falling output does not prove one cause or a definite price direction.', 'Add an explicit energy-capacity limit and separate new/fixed lending shares, or a time-dependent consumption response. Test orders, energy availability, new loan contracts and utilisation over time. Mixed headwinds are plausible, but magnitudes/net inflation remain uncertain.'],
         criteria=['B1: I30/20=1, ΔI−10=1, bedingte−30=1, Altverträge/Timing1.', 'B2: drei getrennte Mechanismen2, verletzte Nachfrageannahme1, Kredit-/Preisgrenze1.', 'B3: konkrete Erweiterung1, fachliche Begründung1, prüfbare Beobachtung1, bedingte Gesamtdiagnose1.'],
         criteria_en=['B1: I30/20=1, ΔI−10=1, conditional−30=1, old contracts/timing1.', 'B2: three channels2, demand assumption failure1, credit/price limit1.', 'B3: concrete extension1, justification1, testable observation1, conditional diagnosis1.']),
    'Wenn die gesamte Arbeit nur Zahlen produziert, ohne einen Nachfrage-/Angebotsmechanismus unter seinen tatsächlichen Annahmen zu erklären, oder historische Quelle und fiktive Modellwerte vollständig gleichsetzt, sind höchstens14 Punkte erreichbar.',
    'If the entire submission only calculates without explaining a demand/supply mechanism under its actual assumptions, or wholly conflates historical evidence and fictional model values, the score is capped at14.',
    ['oil1973'])

add('8ebbbe19', 'Nachfrageboom und Energieengpass: Inflation ursachengerecht bearbeiten', 'Demand boom and energy bottleneck: responding to inflation causes',
    dict(name='Fall A: Zu viel Nachfrage bei vollen Kapazitäten', name_en='Case A: high demand with full capacity',
         dossier='Fiktives Dossier: breite Verbraucherpreise steigen vom Index100 auf106, Produktion um1%, Aufträge um8%; Kapazitäten sind nahezu ausgelastet. Importenergiepreise bleiben stabil. Neue Kredite und Konsumausgaben wachsen kräftig. Drei Unterrichtsoptionen: geldpolitische Dämpfung neuer Finanzierung; ein allgemeiner konsumfördernder Zuschuss; oder befristete Hilfe nur für stark belastete Haushalte, finanziert durch entsprechend geringere andere laufende Nachfrageausgaben. Erwartungen über künftige Preise sind unsicher.',
         dossier_en='Fictional dossier: broad consumer prices100→106, output+1%, orders+8%, near-full capacity, stable imported energy prices. New lending and consumption rise strongly. Classroom choices: restrain new finance through monetary policy; pay a general consumption subsidy; or temporary aid only to highly burdened households funded by equivalent cuts to other current demand spending. Future price expectations are uncertain.',
         prompts=['Diagnostiziere den plausiblen Inflationskanal und prüfe, was die Daten nicht beweisen.', 'Vergleiche die drei Optionen hinsichtlich Nachfrage, Verzögerung, Produktions- und Verteilungsfolgen.', 'Begründe eine bedingte Kombination und eine Information, die deine Entscheidung ändern könnte.'],
         prompts_en=['Diagnose a plausible inflation channel and what the data do not prove.', 'Compare the three options on demand, lags, output and distribution.', 'Justify a conditional combination and information that could change your decision.'],
         solutions=['Preisanstieg6%; Aufträge wachsen schneller als knappes Angebot, stabiler Energiepreis schwächt hier die Energie-Erstursache. Nachfrageüberhang ist plausibel, aber andere Kosten-/Margen-/Produktivitätsdaten fehlen; Kreditgleichzeitigkeit allein beweist keine isolierte Ursache.', 'Höhere Finanzierungskosten können neue Ausgaben verzögert bremsen, belasten Kreditnehmer/Investition/Jobs und fördern nicht jeden Sparer sofort. Allgemeiner Zuschuss kann den Engpass verschärfen. Gezielt gegenfinanzierte Hilfe schützt besonders Betroffene mit geringerer zusätzlicher Gesamtnachfrage, aber unterschiedliche Konsumneigungen und Verwaltung können den Nettoeffekt ändern.', 'Dämpfung mit gezielter sozialer Absicherung ist plausibel, ebenso eine andere begründete Mischung. Bedingung: anhaltender breiter Druck und tatsächliche Transmission, nicht ein einmaliger Einzelpreis. Auslastung, Kernpreistrend, Lohn-/Erwartungsdaten und Kreditreaktion sind relevante Prüfdaten.'],
         solutions_en=['Prices rise6%; orders grow faster than constrained supply, while stable energy prices weaken the initial-energy explanation here. Excess demand is plausible, but cost/margin/productivity evidence is missing; simultaneous credit growth does not prove an isolated cause.', 'Costlier finance can restrain new spending with lags, burden borrowers/investment/jobs and does not immediately reward every saver. A general subsidy may worsen the bottleneck. Targeted offset-funded aid protects those most affected with less added aggregate demand, but spending propensities and administration alter the net effect.', 'Restraint combined with targeted protection is defensible, as is another reasoned mix. Persistent broad pressure and actual transmission matter rather than one relative price. Utilisation, underlying prices, wage/expectation data and lending responses are relevant tests.'],
         criteria=['A1: Rate6%=1, Nachfrage-/Kapazitätsmechanismus1, Energie-Gegenbefund1, Kausalgrenze1.', 'A2: geldpolitische Wirkung/Timing1, Zuschusswirkung1, gezielte Gegenfinanzierung1, Verteilung/Produktionskosten1.', 'A3: begründete Mischung1, Bedingung1, konkrete Daten1, ernsthafter Gegengrund1.'],
         criteria_en=['A1: rate6%=1, demand/capacity1, energy counterevidence1, causal limit1.', 'A2: monetary effect/lag1, subsidy1, targeted offset funding1, distribution/output cost1.', 'A3: reasoned mix1, condition1, data1, counterargument1.']),
    dict(name='Fall B: Weniger Energie, höhere Kosten', name_en='Case B: less energy, higher costs',
         dossier='Anderes fiktives Dossier: Energieimporte fallen mengenmäßig um20%, ihr Preis steigt um40%. Breite Preise steigen8%, Produktion fällt4%. Nominale Lohnverträge werden nun für nächstes Jahr neu verhandelt; erwartete weitere Preissteigerungen können Zweitrundenanpassungen verstärken. Optionen: schneller Ersatz eines Teils der physischen Energieversorgung; pauschale dauerhaft billige Energie aus dem Staatshaushalt ohne Mengenbegrenzung; höhere Finanzierungskosten; befristete gezielte Einkommenshilfe mit ausgewiesener Finanzierung. Lieferersatz ist teuer und schafft nur einen Teil der fehlenden Energie.',
         dossier_en='Another fictional dossier: energy import volumes−20%, energy prices+40%; broad prices+8%, output−4%. Nominal wage contracts are renegotiated for next year, and expectations can amplify second-round adjustments. Options: rapid partial physical replacement; permanently cheap state-funded energy without quantity limits; higher financing costs; or temporary targeted income aid with explicit finance. Replacement is costly and covers only some missing energy.',
         prompts=['Erkläre Erstursache und mögliche Verstärkung. Warum reicht der gleiche Preisanstieg wie in anderen Fällen nicht für dieselbe Diagnose?', 'Vergleiche die Ansatzpunkte der Optionen und ihre Produktions-, Budget- und Anreizgrenzen.', 'Entwickle ein bedingtes Urteil, das Erwartungen, soziale Belastung und Angebotsproblem tatsächlich trennt.'],
         prompts_en=['Explain the initial cause and possible amplification. Why does a similar price rise not imply the same diagnosis?', 'Compare intervention points and output, budget and incentive limits.', 'Develop a conditional judgment distinguishing expectations, social burden and physical supply.'],
         solutions=['Mengenengpass/Kostenanstieg liefert konkrete Angebotshinweise; Preise hoch bei sinkender Produktion. Zweitrunden-Lohn-/Erwartungsanpassung kann persistieren, ist nicht aus dem ersten Energieimpuls automatisch bewiesen. Rate und Ursache sind unterschiedliche Größen.', 'Ersatz hilft physischer Kapazität teilweise und kostet; unbegrenzte Verbilligung belastet Budget und schwächt Sparanreize. Zinsdämpfung kann Nachfrage/Erwartungen beeinflussen, erzeugt aber keine Energie und kann Output zusätzlich drücken. Einkommenshilfe verteilt Lasten, beseitigt den Engpass nicht; Finanzierung und Zielgenauigkeit zählen.', 'Zeitlich begrenzte gezielte Entlastung plus nach Kosten geprüfter Ersatz und Beobachtung von Zweitrunden-/Erwartungsdruck ist plausibel. Stärkere geldpolitische Dämpfung kann bei Entankerung vertretbar sein, nicht als kostenlose Heilung der Erstursache. Nötig: Lieferzeit, Substitutionskosten, Vertrags-/Lohndynamik und finanzielle Tragfähigkeit.'],
         solutions_en=['Volume scarcity and cost rises provide supply evidence; prices rise while output falls. Wage/expectation second rounds can persist but are not automatically proven by the first energy impulse. Rate and cause differ.', 'Replacement partly restores capacity at a cost; unlimited cheap energy burdens budgets and weakens conservation. Rate restraint can affect demand/expectations but creates no energy and may further reduce output. Income support redistributes losses without fixing scarcity; finance and targeting matter.', 'Temporary targeted relief plus cost-checked supply replacement and monitoring of expectations/second rounds is defensible. Stronger monetary restraint may be justified if expectations de-anchor, not as a cost-free cure for the initial cause. Delivery timing, substitution cost, wage contracts and financial viability are needed.'],
         criteria=['B1: Angebots-/Kostenbeleg1, Mengen-/Preiszusammenhang1, Zweitrundenmechanismus1, Ursache/Rategrenze1.', 'B2: physischer Ersatz1, Verbilligungsbudget/Anreiz1, Zinsgrenze1, Hilfe/Finanzierung1.', 'B3: Ursache und Verstärkung trennen1, Sozialabwägung1, bedingte Entscheidung1, relevante Prüfdaten1.'],
         criteria_en=['B1: supply/cost evidence1, quantity/price1, second-round mechanism1, cause/rate limit1.', 'B2: physical replacement1, subsidy budget/incentive1, rate limitation1, relief/finance1.', 'B3: distinguish cause/amplification1, social balance1, conditional decision1, relevant tests1.']),
    'Wenn in der gesamten Arbeit keinerlei materialgestützte Inflationsursache von ihrer Verstärkung unterschieden wird oder kein dazu passender Maßnahmenmechanismus samt realer Grenze erläutert wird, sind höchstens14 Punkte erreichbar.',
    'If the whole submission distinguishes no evidence-based inflation cause from its amplification, or explains no fitting policy mechanism with a real limitation, the score is capped at14.')

add('f70be9a9', 'Preise und Zinsen: Haushalte, Unternehmen und Staat unterscheiden', 'Prices and interest rates: distinguishing households, firms and government',
    dict(name='Fall A: Mehr Geld, weniger Kaufkraft?', name_en='Case A: more money, less purchasing power?',
         dossier='Fiktiver Jahresvergleich mit gleichem vereinfachtem Warenkorb: Preisindex100→110. Haushalt H verdient nominal100→105; Haushalt K behält100. Ein Unternehmen hat unveränderte Absatzmengen, höhere Energie-/Lohnkosten und kann Preise nur teilweise durchsetzen; die genaue Marge fehlt. Der Staat zahlt einen festen Transfer von50 und eine im Unterrichtsvertrag vollständig an diesen Index gekoppelte Zahlung von50. Seine bestehenden festverzinsten Anleihen werden dieses Jahr weder umgeschuldet noch neu verzinst. Dies sind Modellverträge, keine Darstellung bestimmter geltender Sozialleistungsnormen.',
         dossier_en='Fictional annual comparison with an unchanged simplified basket: price index100→110. Household H earns nominal100→105; K retains100. A firm sells unchanged quantities, faces higher energy/wage costs and only partly passes them into prices; its exact margin is unknown. Government pays a fixed transfer50 and a payment50 fully linked to this index by the classroom contract. Existing fixed-rate bonds are neither refinanced nor repriced this year. These are model contracts, not specific current benefit laws.',
         prompts=['Berechne die reale Einkommensänderung von H und die Kaufkraft eines festen Betrags; erläutere die Unterschiede.', 'Analysiere das Unternehmen und die beiden Staatszahlungen. Was verändert sich nominal, real und nur bedingt?', 'Beurteile „10% Inflation belastet alle Akteure gleich und erhöht alle Staatsschuldenzinsen sofort“. Nenne eine konkrete Informationsgrenze.'],
         prompts_en=['Calculate H’s real income change and the purchasing power of a fixed sum; explain the differences.', 'Analyse the firm and both government payments. What changes nominally, in real terms or only conditionally?', 'Assess “10% inflation burdens all actors equally and instantly raises every public debt interest payment”. Give a specific information limit.'],
         solutions=['H:105/110 gegenüber100/100, real−4,55%. K beziehungsweise fixer Betrag:100/110−1≈−9,09%. Nominale+5% gleichen Preis+10% nicht aus; persönliche Gewichte/Verträge können vom Modellkorb abweichen.', 'Die Unternehmensmarge hängt von Kostenstruktur und tatsächlichem Preisaufschlag ab; höhere Kosten allein erlauben keine exakte Gewinnrechnung. Fester Transfer bleibt nominal50, real50/1,1≈45,45 Basiseinheiten. Gekoppelte Zahlung steigt nominal55 und hält im Modell Kaufkraft50. Budgetbelastung und Empfängerwirkung unterscheiden sich.', 'Weder gleiche Belastung noch sofortiger Zinsanstieg sämtlicher Altanleihen folgt. Gläubiger/Schuldnerpositionen, Anpassung, Verbrauchsstruktur und Preisweitergabe unterscheiden sich. Festzinsverträge bleiben zunächst gleich; Neu-/Refinanzierung und indexierte Ansprüche sind gesondert zu prüfen.'],
         solutions_en=['H:105/110 relative to100/100, real−4.55%. K or a fixed sum:100/110−1≈−9.09%. Nominal+5% does not offset prices+10%; personal weights/contracts can differ from the model basket.', 'The firm’s margin depends on cost structure and actual price pass-through; cost rises alone do not determine exact profit. Fixed transfer remains nominal50, real50/1.1≈45.45 base units. The linked payment becomes55 nominal and retains model purchasing power50. Budget and recipient effects differ.', 'Neither equal burdens nor instant repricing of all old bonds follows. Creditor/debtor positions, adjustments, consumption composition and pass-through differ. Fixed-rate contracts initially remain unchanged; new/refinanced debt and linked claims need separate analysis.'],
         criteria=['A1: H≈−4,55%=1, fixer Betrag≈−9,09%=1, Nominal/Real1, Korb-/Vertragsgrenze1.', 'A2: Unternehmensmechanismus/Grenze1, fixer Transfer1, gekoppelte Zahlung1, Staats-/Empfängerwirkung1.', 'A3: alle drei Akteure unterscheiden1, Gleichbelastung widerlegen1, Altzins-/Refinanzierungsgrenze1, konkrete Zusatzinformation1.'],
         criteria_en=['A1: H≈−4.55%=1, fixed sum≈−9.09%=1, nominal/real1, basket/contract limit1.', 'A2: firm mechanism/limit1, fixed transfer1, linked payment1, government/recipient effect1.', 'A3: distinguish all three actors1, unequal burdens1, fixed/refinancing limit1, added information1.']),
    dict(name='Fall B: Ein höherer Leitzins trifft verschiedene Verträge', name_en='Case B: a higher policy rate meets different contracts',
         dossier='Anderes fiktives Dossier: Leitzins3%→4%. Bank X erhöht neue variable Kreditzinsen von5% auf5,8%, neue Einlagenzinsen von2% auf2,5%. Haushalt A hat einen bis in drei Jahren festen Kredit100 zu5%; Haushalt B hat einen jetzt angepassten variablen Kredit100. Ein Betrieb plant eine neue Investition mit Kredit200. Der Staat besitzt nur festverzinste Anleihen1000 zu3%, die erst in zwei Jahren refinanziert werden. Keine Angabe über dann geltende Zinsen oder das Verhalten anderer Banken. Alle Zinsen gelten im Modell jährlich auf unveränderten Kapitalbetrag; Tilgung wird für die Rechnung ignoriert.',
         dossier_en='Another fictional dossier: policy rate3%→4%. Bank X raises new variable lending5%→5.8% and new deposit rates2%→2.5%. Household A has a100 fixed loan at5% for another three years; B has a100 variable loan adjusted now. A firm plans a new200-funded investment. Government has only fixed1000 bonds at3%, refinanced in two years. Future rates and other banks’ behaviour are unknown. Annual rates apply to unchanged principal; repayment is ignored for calculation.',
         prompts=['Berechne die unmittelbaren jährlichen Zinswirkungen für A, B, den neuen Betriebskredit und bestehende Staatsschulden.', 'Erkläre mögliche Ausgaben-, Spar- und Investitionswirkungen für alle drei Akteursgruppen und den begrenzten Durchgriff des Leitzinses.', 'Prüfe eine Behauptung sofortiger identischer Weitergabe. Welche Daten und zeitlichen Bedingungen sind für eine belastbare Entscheidung nötig?'],
         prompts_en=['Calculate immediate annual interest effects for A, B, the new business loan and existing public debt.', 'Explain possible spending, saving and investment effects across all three groups and limited policy-rate pass-through.', 'Assess instant identical pass-through; what evidence and timing conditions are needed for a sound decision?'],
         solutions=['A bleibt5, B steigt5→5,8 also+0,8; neuer Betriebskredit10→11,6 also+1,6; Staat zahlt zunächst30 unverändert. Ein neuer Einlagenbetrag100 bei X würde2→2,5 erzielen, nicht automatisch+1. Zahlen sind nur Vertragsrechnung, keine sichere Verhaltensänderung.', 'B hat weniger verfügbares Einkommen bei sonst Gleichem, A zunächst keinen neuen Kreditzins; neue Sparer können mehr Ertrag bekommen. Betrieb vergleicht höhere Finanzierungskosten mit erwarteten Erträgen/Risiko, Investition kann sinken. Staat ist erst bei späterer Refinanzierung betroffen; künftiger Satz unbekannt. Kreditangebot, Laufzeit, Wettbewerb und Bonität vermitteln den Leitzins.', 'X gibt+1 Leitzins nur als+0,8 Kreditzins und+0,5 Einlagenzins weiter, Altverträge noch gar nicht. Benötigt werden Vertragsanteile, Ertragsaussichten, Bankpolitik und Refinanzierungszeit. Ein mögliches Nachfrageminus ist bedingt, keine Gewissheit für jeden Haushalt/Betrieb/Staat.'],
         solutions_en=['A remains5; B rises5→5.8, +0.8; the new firm loan10→11.6, +1.6; government initially pays30 unchanged. A new100 deposit at X earns2→2.5, not automatically+1. Contract calculations do not establish behaviour.', 'B has less disposable income otherwise unchanged; A initially has no new loan cost, while new savers may earn more. The firm balances cost against expected return/risk, potentially reducing investment. Government is affected upon later refinancing at an unknown rate. Lending supply, maturity, competition and risk mediate the policy rate.', 'X transmits the+1 policy move as+0.8 lending and+0.5 deposit rates; fixed contracts do not move yet. Contract shares, returns, bank policies and refinancing timing are needed. Potential demand reduction is conditional, not certain for every actor.'],
         criteria=['B1: vier Kredit-/Anleihewerte2, neue Einlage1, keine Verhaltensgewissheit1.', 'B2: Haushalt1, Unternehmen1, Staat1, begrenzte Transmission1.', 'B3: unterschiedliche Weitergabe1, Neu/Alt/Timing1, konkrete Daten1, bedingtes Urteil1.'],
         criteria_en=['B1: four loan/bond values2, new deposit1, no behavioural certainty1.', 'B2: household1, firm1, government1, limited transmission1.', 'B3: unequal pass-through1, new/old/timing1, data1, conditional judgment1.']),
    'Wenn die gesamte Arbeit nominale von realen Preisfolgen überhaupt nicht unterscheidet oder keinerlei Vertrags-/Weitergabebedingungen der Zinswirkungen erklärt, oder eine der drei Akteursgruppen vollständig ohne fachliche Wirkungsanalyse bleibt, sind höchstens14 Punkte erreichbar.',
    'If the whole submission does not distinguish nominal/real price effects at all or explains no contractual/pass-through conditions, or entirely omits substantive effect analysis for one of the three actor groups, the score is capped at14.')

add('6f1f4654', 'Vier gesetzliche Ziele und zwei widersprüchliche Wirtschaftslagen', 'Four statutory objectives and two conflicting economic situations',
    dict(name='Fall A: Erholung mit Nebenwirkungen', name_en='Case A: recovery with side effects',
         dossier='Amtliche Normhilfe, §1 StabG: Bund und Länder sollen wirtschafts-/finanzpolitisch im marktwirtschaftlichen Rahmen zur Preisniveaustabilität, hohem Beschäftigungsstand, außenwirtschaftlichem Gleichgewicht sowie stetigem und angemessenem Wachstum beitragen; https://www.gesetze-im-internet.de/stabg/__1.html. Der Paragraph nennt dafür keine hier einzusetzenden festen Prozentgrenzen. Fiktive Jahresdaten: reale Produktion+3%, Arbeitslosenquote8%→6%, breite Preise+5%, Leistungsbilanzsaldo−4% des BIP nach−1%. Eine Infrastrukturmaßnahme kann Beschäftigung stärken, benötigt aber knappe Baukapazität und importierte Ausrüstung. Umweltbelastung ist eine zusätzliche begründbare politische Perspektive, kein fünftes wörtliches Ziel dieses Paragraphen.',
         dossier_en='Official statutory aid, section1 StabG: federal/state economic and fiscal measures within a market economy should contribute to stable prices, high employment, external balance and steady appropriate growth; https://www.gesetze-im-internet.de/stabg/__1.html. The section supplies no fixed percentage cutoffs for this exercise. Fictional annual data: real output+3%, unemployment8%→6%, broad prices+5%, current-account balance−4% of GDP after−1%. Infrastructure can support employment but needs scarce construction capacity and imported equipment. Environmental impacts are an additional defensible policy perspective, not a fifth literal objective in this section.',
         prompts=['Ordne alle vier gesetzlichen Ziele den Daten zu und kennzeichne, welche Zielerreichung nur eingeschränkt beurteilt werden kann.', 'Erkläre zwei fallbezogene Zielbeziehungen der Infrastrukturmaßnahme einschließlich eines Konflikts.', 'Entwickle eine begründete Priorität mit Gegenposition und zusätzlicher Information; trenne gesetzliche Ziele von deiner ergänzenden Wertung.'],
         prompts_en=['Connect all four statutory objectives to the data, stating where attainment remains uncertain.', 'Explain two case-specific objective relationships for infrastructure, including a conflict.', 'Develop a reasoned priority against a competing view, separating statutory objectives from your additional evaluation.'],
         solutions=['Beschäftigung verbessert sich laut Arbeitslosenquote, ist nicht allein daraus vollständig beurteilt; Wachstum ist realpositiv, Stetigkeit braucht Zeitreihe.5% Preissteigerung signalisiert Stabilitätsproblem, keine frei erfundene gesetzliche Grenzüberschreitung. Größeres Defizit ist Außenindikator und untersuchungsbedürftig; Ursache/Finanzierung/Zeithorizont entscheiden, nicht automatisch jeder Import.', 'Zusätzliche Produktion/Jobs können Wachstum und Beschäftigung gemeinsam fördern. Bei knappen Baukapazitäten entsteht Preis-/Verdrängungsdruck; Importbedarf kann zunächst das Außenbild belasten. Längerfristige Produktivität ist möglich, nicht garantiert. Umweltperspektive muss gesondert mit Wirkung begründet werden.', 'Priorisierung von gezielter zeitlich gestreckter Infrastruktur oder zunächst Preisentlastung ist bei konkretem Konflikt begründbar. Gegengrund: Job-/Investitionsverluste durch Verzögerung. Benötigt werden Bauauslastung, Arbeitsmarktbreite, Außenfinanzierung und Wachstumsdauer; §1 wird nicht zum numerischen Automatismus.'],
         solutions_en=['Employment improves by unemployment data, but that alone is incomplete; growth is positive in real terms, while steadiness needs a series.5% price growth signals a stability problem, not an invented statutory cutoff. The larger deficit needs analysis of causes, finance and horizon, not automatic condemnation of every import.', 'Higher output/jobs may jointly support growth and employment. Scarce construction creates price/crowding pressure; imports may initially weaken the external position. Long-term productivity is possible, not guaranteed. Environmental evaluation needs its own mechanism.', 'Targeted staged infrastructure or initial price relief can be prioritised through the concrete conflict. A counterargument is lost jobs/investment from delay. Construction utilisation, wider labour data, external finance and growth persistence are needed; section1 is not a numerical automatic rule.'],
         criteria=['A1: vier Ziele korrekt den Daten zuordnen2, Stetigkeits-/Beschäftigungsgrenze1, keine erfundene Rechtsgrenze1.', 'A2: Zielharmonie1, konkreter Konflikt1, Wirkungsmechanismus1, bedingte Zeitperspektive1.', 'A3: begründete Priorität1, Gegenposition1, Zusatzdaten1, gesetzlich/zusätzlich trennen1.'],
         criteria_en=['A1: four correctly linked objectives2, persistence/employment limit1, no invented legal cutoff1.', 'A2: synergy1, specific conflict1, mechanism1, conditional horizon1.', 'A3: reasoned priority1, competing view1, added data1, statutory/additional1.']),
    dict(name='Fall B: Stabile Preise reichen nicht', name_en='Case B: stable prices are not enough',
         dossier='Andere fiktive Lage über drei Jahre: breite Preisraten1%,1%,1%; reale Wachstumsraten0%,−1%,0%; Arbeitslosenquote9%,10%,10%; Leistungsbilanzüberschuss jeweils8% des BIP. Eine diskutierte steuerfinanzierte Weiterbildungs-/Investitionsmaßnahme kann erst nach einem Jahr zusätzliche produktive Kapazität schaffen. Es fehlen Beschäftigungsquoten, Außenhandelsursachen und private Investitionserwartungen. Benutze dieselbe §1-Normhilfe; keine Prozentwerte sind vom Paragraphen als feste Grenzmarken festgelegt.',
         dossier_en='Another fictional three-year situation: broad price rates1%,1%,1%; real growth0%,−1%,0%; unemployment9%,10%,10%; current-account surplus8% of GDP each year. A tax-funded training/investment proposal can add productive capacity only after a year. Employment rates, external-balance causes and private investment expectations are missing. Use the same section1 aid; its text sets none of these numbers as cutoffs.',
         prompts=['Beurteile die Aussage „Niedrige Inflation und hoher Überschuss bedeuten, dass alle vier Ziele erreicht sind“.', 'Analysiere mögliche Harmonie und Konflikte der Maßnahme über kurze und längere Frist.', 'Formuliere ein bedingtes Gesamturteil mit Gegenargument und Messgrenze.'],
         prompts_en=['Assess “low inflation and a large surplus mean all four objectives are achieved”.', 'Analyse possible synergies and conflicts over short and longer horizons.', 'Give a conditional overall judgment with a counterargument and measurement limit.'],
         solutions=['Preisbild relativ stabil, aber hohe/steigende Arbeitslosigkeit und stagnierende/fallende reale Produktion sprechen gegen pauschale Zielerreichung. Überschuss ist nicht automatisch außenwirtschaftliches Gleichgewicht; Ursache, Gegenpositionen und Dauer fehlen. Vierzielprüfung, keine Einzahlbewertung.', 'Längerfristige Qualifikation kann Produktivität/Jobs verbinden; Wirkung erst nach einem Jahr, kurzfristige Steuerlast kann Nachfrage mindern. Verdrängung, Umsetzung und reale Nutzbarkeit sind Bedingungen; importierte Güter oder exportfähige Produktion beeinflussen Außenbalance unterschiedlich.', 'Bedingt gezielte Investition mit überprüfter Beschäftigungs-/Wachstumswirkung vertretbar; eine andere Priorität braucht konkrete Begründung. Gegengrund sind Finanzierung/geringe Wirksamkeit. Konkrete Zeitreihe der Beschäftigung, Investitionsnachfrage und Saldenstruktur helfen; keine Gleichsetzung hoher Exporte mit garantiertem Gesamtwohlstand.'],
         solutions_en=['Prices are relatively stable, but high/rising unemployment and flat/falling real output contradict universal attainment. A surplus is not automatically external balance; causes, counterpart positions and persistence matter. Analyse four objectives rather than one number.', 'Training may combine productivity and jobs later; effects take a year and taxation may reduce near-term demand. Crowding, implementation and actual skill use matter; imported equipment or exportable output affects external balance differently.', 'Targeted investment with verified employment/growth effects is conditionally defensible; other priorities need specific reasons. Funding and ineffectiveness are counterarguments. Employment data, investment demand and balance composition help; high exports do not guarantee overall welfare.'],
         criteria=['B1: vierzielbezogene Gegenprüfung2, Überschuss/Gleichgewicht1, fehlende Schwellen/Messgrenze1.', 'B2: längerfristige Harmonie1, kurzfristiger Konflikt1, Finanzierung/Timing1, Außen-/Umsetzungsbedingung1.', 'B3: Gesamturteil1, Gegengrund1, konkrete Messinformation1, Bedingtheit statt Einzahlregel1.'],
         criteria_en=['B1: four-objective review2, surplus/balance1, cutoff/measurement limit1.', 'B2: longer-run synergy1, short-run conflict1, finance/timing1, external/implementation condition1.', 'B3: overall judgment1, counterargument1, measurement evidence1, conditional rather than single-number rule1.']),
    'Wenn die gesamte Arbeit die vier gesetzlichen Ziele nicht fallbezogen unterscheidet oder keinerlei begründete Zielbeziehung/Abwägung zeigt, sind höchstens14 Punkte erreichbar.',
    'If the entire submission does not distinguish the four statutory objectives within the cases, or shows no reasoned relationship/trade-off, the score is capped at14.',
    ['stabg1'])

add('550a050a', 'Fiskalpolitik zwischen schneller Hilfe und später Wirkung', 'Fiscal policy between rapid relief and delayed effects',
    dict(name='Fall A: Eine Rezession und drei Zeitpläne', name_en='Case A: recession and three timelines',
         dossier='Fiktiver Abschwung: Produktion−3%, steigende Arbeitslosigkeit, freie Kapazität. Bestehende Unterrichtsregeln erhöhen automatisch Arbeitslosenleistungen, wenn Menschen ihren Job verlieren; ohne neuen Beschluss steigt die Auszahlung um6. Alternative zusätzliche Beschlüsse: sofortige befristete Überweisung10 an Haushalte mit geringem Einkommen, erwartete kurzfristige Konsumquote0,8; oder Bauprojekt10, dessen erste Auszahlungen und Aufträge in zwei Jahren beginnen. Bei der Überweisung wird für den einfachen Erstimpuls kein gleichzeitiger Ausgabenkürzungs-/Steuerschritt unterstellt; Finanzierung erfolgt durch zusätzlichen Kredit, dessen Kosten unbekannt sind. Eine feste Multiplikatorgarantie wird nicht gegeben.',
         dossier_en='Fictional downturn: output−3%, rising unemployment and spare capacity. Existing classroom rules automatically raise unemployment benefits when jobs are lost, adding6 without a new decision. Discretionary alternatives: an immediate temporary10 transfer to low-income households with an expected short-run consumption share0.8; or a10 building project whose first payments/orders begin in two years. The simple initial transfer impulse assumes no simultaneous tax/spending offset; extra borrowing finances it at unknown cost. No fixed multiplier is guaranteed.',
         prompts=['Unterscheide automatische und diskretionäre Reaktion und berechne den erwarteten ersten Konsumimpuls des Transfers.', 'Vergleiche Transfer und Bauprojekt für kurzfristige Stabilisierung sowie längerfristige Wirkung und Finanzierung.', 'Begründe eine bedingte Wahl gegen eine andere Priorität; welche Information könnte das Urteil ändern?'],
         prompts_en=['Distinguish automatic/discretionary responses and calculate the transfer’s expected first consumption impulse.', 'Compare transfer and construction for short-run stabilisation, longer-run effects and financing.', 'Choose conditionally against another priority; what information could change the decision?'],
         solutions=['Bestehende Leistungsregel wirkt automatisch+6, neuer10-Transfer/Bau erfordert Beschluss. Erwarteter erster Konsum8, restliche2 zunächst gespart; kein gesicherter Gesamteffekt8 oder größer, da Quote/Importe/Reaktionen unsicher.', 'Transfer erreicht laufende Nachfrage schneller; Targeting/Verwaltung, Sparen und Verschuldung begrenzen. Bau kann Infrastruktur/Produktivität stärken, hat im gegebenen Zeitplan aber keinen jetzigen Auftragseffekt. Beide kosten Ressourcen; Kreditzins, spätere Finanzierung und freie fachliche Baukapazität sind Bedingungen.', 'Für akut freie Kapazität plausibel schnell gezielter Transfer neben automatischer Stabilisierung, Bau separat langfristig prüfen. Ein gut vorbereiteter späterer Aufbau kann trotzdem wichtig sein. Erwartete Abschwungdauer, Empfängerreaktion, Finanzierung und Umsetzungszeit entscheiden; kein universeller Expansionsbefehl.'],
         solutions_en=['Existing benefits automatically add6; a new10 transfer/project needs a decision. Expected initial consumption8, leaving2 initially saved; no certain total effect of8 or more because spending, imports and reactions are uncertain.', 'Transfers support current demand sooner; targeting, administration, saving and debt constrain them. Construction may improve infrastructure/productivity but creates no current orders under the stated schedule. Both use resources; borrowing cost, future finance and skilled construction capacity matter.', 'With acute spare capacity, a rapid targeted transfer alongside automatic stabilisation is defensible, with construction assessed separately for the long term. A prepared later programme may still matter. Downturn duration, recipient behaviour, finance and timing determine the choice; no universal expansion rule.'],
         criteria=['A1: automatisch/diskretionär2, Konsum8=1, Erstimpuls/Gesamteffektgrenze1.', 'A2: kurzfristiger Zeitvergleich1, langfristiger Bauwert1, Transfergrenze1, Finanzierung1.', 'A3: bedingte Wahl1, Gegenpriorität1, konkrete Information1, Wirkungsmechanismus1.'],
         criteria_en=['A1: automatic/discretionary2, consumption8=1, initial/total limit1.', 'A2: short-run timing1, construction’s longer-run value1, transfer limit1, finance1.', 'A3: conditional choice1, competing priority1, information1, mechanism1.']),
    dict(name='Fall B: Nachfrage auf voller Auslastung', name_en='Case B: demand at full utilisation',
         dossier='Andere fiktive Wirtschaft: hohe Auslastung, breite Preise+6%, wachsende Auftragsschlange. Eine zusätzliche unbefristete Steuersenkung würde das verfügbare Einkommen sämtlicher Haushalte sofort um20 erhöhen und durch Kredit finanziert. Ein früher befristetes Nachfrageprogramm10 läuft planmäßig aus. Alternative: eng gezielte Hilfe3 für besonders betroffene Haushalte mit Kürzung anderer laufender Ausgaben3. Welche Gruppen die Kürzung tragen und wie ihre Konsumquoten sind, ist unbekannt. Keine geltenden Steuer-/Schuldenregeln werden behauptet.',
         dossier_en='Another fictional economy: high utilisation, broad prices+6% and growing order backlog. An additional permanent tax cut immediately raises all households’ disposable income20, financed by borrowing. A previously temporary demand programme10 expires as scheduled. Alternatively, tightly targeted aid3 is offset by current spending cuts3; the affected groups and spending shares are unknown. No current tax or debt laws are asserted.',
         prompts=['Erkläre, warum dieselbe expansive Richtung wie in Fall A hier anders zu beurteilen ist.', 'Vergleiche Steuersenkung, planmäßiges Auslaufen und gezielte gegenfinanzierte Hilfe hinsichtlich Nachfrage, Verteilung und Dauer.', 'Entwickle ein bedingtes Stabilisierungskonzept mit Finanzierungs-/Informationsgrenze und ernsthafter Gegenposition.'],
         prompts_en=['Explain why the same expansionary direction as in A needs a different assessment here.', 'Compare the tax cut, planned expiry and offset-funded aid on demand, distribution and duration.', 'Design a conditional stabilisation approach with a finance/information limit and serious competing position.'],
         solutions=['Bei schon knappem Angebot erhöht breite neue Nachfrage eher Preis-/Verdrängungsdruck als freie reale Produktion. Der freie-Kapazität-Mechanismus aus A gilt nicht unverändert; Größe/Timing und Investitionsreaktionen bleiben Datenfragen.', 'Steuersenkung stärkt verfügbare Mittel breit und dauerhaft, braucht Kredit/weitere Finanzierung; höhere Sparquote kann dämpfen. Auslaufen reduziert zusätzlichen Nachfrageimpuls, kann betroffene Jobs/Einkommen belasten. Gegenfinanzierte gezielte Hilfe verteilt Mittel um, Netto-Nachfrage hängt von unterschiedlichen Konsumquoten ab und ist nicht sicher null.', 'Plausibel planmäßiges Auslaufen mit gezielter überprüfter Absicherung; eine andere Wahl muss Knappheit/Preis- und Verteilungskonflikt begründen. Informationen zu Empfängern/Kürzungsträgern, Auslastung und Budgetwirkung nötig. Kurzfristige Hilfe und dauerhafte Ausweitung nicht verwechseln; keine kostenlose Steuerwirkung.'],
         solutions_en=['With supply already constrained, broad new demand is more likely to add prices/crowding than free real output. A’s spare-capacity mechanism does not carry over unchanged; size, timing and investment responses need evidence.', 'The tax cut increases disposable resources widely and permanently but needs credit/future finance; saving can reduce its impulse. Expiry removes added demand and may hurt affected jobs/incomes. Offset-funded targeted help redistributes spending, but net demand depends on differing propensities and is not certainly zero.', 'Planned expiry with targeted monitored protection is defensible; alternatives must address scarcity, prices and distribution. Recipient/cut-bearing groups, utilisation and budget effects are needed. Distinguish temporary aid from lasting expansion; tax effects are not free.'],
         criteria=['B1: Auslastung1, Nachfrage-/Preiskette1, Unterschied zu A1, Bedingtheit1.', 'B2: Steuerdauer/Finanzierung1, Auslaufwirkung1, Zielhilfe/Verteilung1, Netto-Nachfragegrenze1.', 'B3: Konzept/Mechanismus1, Gegengrund1, Finanzierungsgrenze1, konkrete Prüfdaten1.'],
         criteria_en=['B1: utilisation1, demand/price chain1, difference from A1, conditionality1.', 'B2: tax duration/funding1, expiry1, targeting/distribution1, net-demand limit1.', 'B3: approach/mechanism1, counterargument1, funding limit1, specific evidence1.']),
    'Wenn in der gesamten Arbeit automatische und diskretionäre Fiskalreaktionen überhaupt nicht funktional unterschieden werden oder keine konjunkturabhängige Maßnahmenwirkung mit Zeit-/Finanzierungsgrenze erklärt wird, sind höchstens14 Punkte erreichbar.',
    'If the whole submission does not distinguish automatic/discretionary fiscal responses at all or explains no cycle-dependent policy effect with timing/funding limits, the score is capped at14.')

add('a773d8a6', 'Konjunkturindikatoren mit Bezugsgrößen und Zeitverzug lesen', 'Reading cycle indicators with reference bases and lags',
    dict(name='Fall A: Aufträge drehen früher als Beschäftigung', name_en='Case A: orders turn before employment',
         dossier='Fiktive Monatsreihe, saisonbereinigt: Auftragseingangsindex100→104→108; realer Produktionsindex100→98→97; Arbeitslosenquote6,0%→6,2%→6,4%. Auslastung ist nicht erhoben. Aufträge beziehen sich auf künftige Lieferungen und können storniert werden; Produktion auf im jeweiligen Monat gefertigte Mengen. Beide Indizes haben denselben Basiswert100, messen aber verschiedene Dinge. Die Arbeitslosenquote ist ein Anteil, keine Indexzahl. Keine amtliche Datenreihe wird nachgebildet.',
         dossier_en='Fictional seasonally adjusted monthly series: orders index100→104→108; real production100→98→97; unemployment6.0%→6.2%→6.4%. Utilisation is missing. Orders concern future deliveries and can be cancelled; output concerns goods produced each month. Both indices start at100 but measure different things. Unemployment is a share, not an index. No official series is reproduced.',
         prompts=['Berechne die letzte monatliche Veränderung der Aufträge und Produktion sowie die Änderung der Arbeitslosenquote.', 'Erkläre Vorlauf/Nachlauf und widersprüchliche Hinweise, ohne einen Indikator zu ignorieren.', 'Entwickle eine vorsichtige Phasendiagnose mit einer konkurrierenden Erklärung und konkretem Datenbedarf.'],
         prompts_en=['Calculate the latest monthly order/output changes and unemployment-rate change.', 'Explain leads/lags and conflicting evidence without ignoring a series.', 'Develop a cautious phase diagnosis with an alternative explanation and specific evidence needs.'],
         solutions=['Aufträge+4/104≈3,85%; Produktion−1/98≈−1,02%; Arbeitslosigkeit+0,2 Prozentpunkte, nicht+0,2% relativ. Indexstand108 ist8% über Basis, nicht aktuelle Monatsrate8%.', 'Neue Aufträge können vor Produktion/Jobs drehen. Produktion fällt noch, Jobs reagieren verzögert; das passt möglicherweise zu frühem Wendepunkt, beweist ihn nicht. Stornos, Lieferengpässe oder Sonderaufträge können Widerspruch anders erklären.', 'Frühe Erholungshinweise bei noch schwacher aktueller Aktivität sind plausibel, sichere Boomdiagnose nicht. Benötigt: Auslastung, Auftragsbeständigkeit, reale Umsätze, breitere Branchenreihe und Folgemonate. Eine fortgesetzte Schwäche mit bloß kurzlebigem Auftragsplus ist Gegenhypothese.'],
         solutions_en=['Orders+4/104≈3.85%; output−1/98≈−1.02%; unemployment+0.2 percentage points, not relative+0.2%. Index108 is8% above base, not an8% current monthly rate.', 'Orders may turn before output/jobs. Output still falls and employment reacts later; this may fit an early turn without proving it. Cancellations, bottlenecks or exceptional orders can also explain the contradiction.', 'Early recovery signals alongside weak current activity are plausible, not a certain boom. Need utilisation, order durability, real sales, broader sectors and later months. Continued weakness with a temporary order jump is an alternative.'],
         criteria=['A1: Aufträge≈3,85%=1, Produktion≈−1,02%=1, Quote+0,2pp=1, Niveau/Rate1.', 'A2: Vorlauf1, Beschäftigungsverzug1, gemeinsame Widerspruchsdeutung1, keine Garantie1.', 'A3: bedingte Phase1, Gegenhypothese1, relevante Zusatzdaten1, Zeit-/Branchenbezug1.'],
         criteria_en=['A1: orders≈3.85%=1, output≈−1.02%=1, unemployment+0.2pp=1, level/rate1.', 'A2: leading orders1, employment lag1, joint interpretation1, no guarantee1.', 'A3: conditional phase1, alternative1, relevant data1, time/sector1.']),
    dict(name='Fall B: Nominaler Umsatz täuscht', name_en='Case B: nominal sales mislead',
         dossier='Andere fiktive Jahresreihe: nominaler Umsatz100→108, passender Preisindex100→112. Auslastung85%→78%. Anteil der befragten Betriebe mit Investitionsausweitung50%→35%; diese Pläne sind keine bereits ausgeführten Investitionen. Um die reale Umsatzentwicklung zu schätzen, werden für den Unterricht unveränderte Güterstruktur und ein passender Deflator angenommen. Ein Kommentar nennt108 einen „sicheren Boom“.',
         dossier_en='Another fictional annual series: nominal sales100→108, matching price index100→112; utilisation85%→78%. Firms planning investment expansion50%→35%; plans are not implemented investment. Estimating real sales assumes an unchanged product composition and suitable deflator. A commentator calls108 a “certain boom”.',
         prompts=['Berechne die reale Umsatzänderung, die Auslastungs- und Plananteilsänderung. Unterscheide Prozentpunkte und Prozent.', 'Verknüpfe die drei Indikatoren und beurteile den Kommentar samt Grenze der Deflator-/Umfrageannahme.', 'Formuliere eine bedingte Diagnose und eine prüfbare Variation: Was wäre bei sinkendem Preisindex und steigender Auslastung anders?'],
         prompts_en=['Calculate real sales, utilisation and plan-share changes, separating percentages and percentage points.', 'Combine the indicators and assess the comment plus deflator/survey limitations.', 'Give a conditional diagnosis and testable variation: what changes if prices fall and utilisation rises?'],
         solutions=['Realer Vergleich108/112 gegenüber1:−3,57%; Auslastung−7 Prozentpunkte; Plananteil−15pp, relativ−30%. Nominalumsatz+8% ist nicht real+8%.', 'Realumsatz und Auslastung sinken, Investitionspläne schwächer: Boom nicht gedeckt. Pläne sind Vorlauf-/Erwartungshinweise, keine sicheren Mengen; ungeeigneter Deflator oder geänderte Güterstruktur könnte die Realrechnung verzerren.', 'Schwäche-/Abschwunghinweise sind plausibel, genaue Phasengrenze braucht weitere Reihe/Branchen. Sinkende Preise und steigende Auslastung könnten reale Mengenentwicklung günstiger erscheinen lassen; nicht automatisch Boom, weil Größen und übrige Hinweise fehlen. Reale Produktion, Aufträge und tatsächliche Investitionen prüfen.'],
         solutions_en=['Real comparison108/112−1≈−3.57%; utilisation−7 percentage points; plan share−15pp, relatively−30%. Nominal+8% is not real+8%.', 'Real sales/utilisation fall and investment intentions weaken: a boom is unsupported. Plans are leading/expectational signals, not certain volumes; an unsuitable deflator or changing composition can distort the estimate.', 'Weakness/downturn signals are plausible, but exact phase boundaries require more periods/sectors. Falling prices and rising utilisation could imply a better real-volume picture, not an automatic boom without sizes/other evidence. Check real production, orders and actual investment.'],
         criteria=['B1: real≈−3,57%=1, Auslastung−7pp=1, Pläne−15pp/−30%=1, nominal/real1.', 'B2: drei Hinweise verbinden1, Boomurteil1, Pläne/Mengen1, Deflator-/Strukturgrenze1.', 'B3: bedingte Phase1, Variation sachlich1, fehlende Größen/Grenze1, prüfbare Zusatzreihe1.'],
         criteria_en=['B1: real≈−3.57%=1, utilisation−7pp=1, plans−15pp/−30%=1, nominal/real1.', 'B2: combine three signals1, boom judgment1, intentions/volumes1, deflator/composition1.', 'B3: conditional phase1, valid variation1, missing sizes/limit1, testable additional series1.']),
    'Wenn die gesamte Arbeit allein Einzelzahlen auflistet, ohne mehrere Indikatoren unter Bezugsgrößen-/Zeitverzugsbedingungen zu einer begründeten bedingten Diagnose zu verbinden, sind höchstens14 Punkte erreichbar.',
    'If the whole submission merely lists numbers without combining indicators, reference bases and timing into a reasoned conditional diagnosis, the score is capped at14.')

add('0e5b12a1', 'Prognosen vergleichen, Fehler erklären und nach einem Schock revidieren', 'Comparing forecasts, explaining errors and updating after a shock',
    dict(name='Fall A: Punktwert, Band und Bedingung', name_en='Case A: point estimate, range and condition',
         dossier='Fiktive Prognosen für dieselbe reale Jahreswachstumsrate: Institut A veröffentlicht im Januar1,5% und ein ausdrücklich nicht probabilistisch interpretiertes Unsicherheitsband0,5–2,5%. Institut B veröffentlicht im Februar2,0% unter der Bedingung fallender Energiepreise. Gemessener späterer Jahreswert1,0%. Energie wurde entgegen B teurer; A und B hatten unterschiedliche Januar-/Februar-Datenstände. Es fehlen einheitliche Modelle und mehrere Vergleichsjahre. Keinem Band wird eine80%- oder95%-Wahrscheinlichkeit zugeordnet.',
         dossier_en='Fictional forecasts for the same annual real growth: institute A issues1.5% in January with an explicitly non-probabilistic uncertainty range0.5–2.5%. B issues2.0% in February conditional on falling energy prices. Later measured growth is1.0%. Energy rose contrary to B’s condition; A/B used different January/February vintages. Common models and multiple comparison years are missing. The range carries no80% or95% probability.',
         prompts=['Berechne die beiden Punktfehler in Prozentpunkten und interpretiere das Band sowie die Bedingung.', 'Beurteile „A ist erwiesenermaßen generell besser, B nutzlos“. Trenne Datenstand, Modell, Annahme und tatsächlich messbaren Fehler.', 'Formuliere eine sachliche Revision für B und eine faire Vergleichsregel mit zusätzlicher Information.'],
         prompts_en=['Calculate point errors in percentage points and interpret the range and condition.', 'Assess “A is proven universally better and B useless”, separating vintage, model, assumption and observed error.', 'Specify a sound revision for B and a fair comparison rule with added information.'],
         solutions=['Prognose minus Ist: A+0,5pp, B+1,0pp; absolute Fehler0,5/1,0.1,0 liegt im A-Band, garantiert aber weder Modellrichtigkeit noch bekannte Trefferwahrscheinlichkeit. Bs2,0 gilt unter Energieannahme, deren Scheitern nicht ignoriert werden darf.', 'Für dieses Jahr liegt A-Punkt näher; eine allgemeine Qualitätsrangfolge folgt nicht aus einem Jahr mit verschiedenen Datenständen. Annahmefehler, neue Daten und Modellfehler trennen; eine bedingte Prognose kann informativ bleiben, auch wenn die Bedingung nicht eintritt. Gleicher Horizont/Variable/Vintage und viele Fälle nötig.', 'Aktualisierte Energie-/Nachfrageinformationen in B einarbeiten, neuen Wert oder mehrere offen datierte Szenarien mit Unsicherheit veröffentlichen; Revision begründen statt alten Wert als sicher verteidigen. Vergleiche gleiche Vorhersagezeitpunkte, Maße und mehrere Fehler/Abdeckungen ohne erfundene Wahrscheinlichkeiten.'],
         solutions_en=['Forecast minus outcome: A+0.5pp, B+1.0pp; absolute errors0.5/1.0. Outcome1.0 is inside A’s range, proving neither the model nor a known coverage probability. B’s2.0 was conditional on energy, which failed.', 'A’s point is closer this year; one year with different vintages cannot establish general quality. Separate assumption failure, new information and model error; a conditional forecast can remain informative when its condition fails. Equal horizon/variable/vintage and many cases are needed.', 'Incorporate updated energy/demand information, publish a newly dated estimate or explicit scenarios and uncertainty, explain the revision rather than defend certainty. Compare matched prediction dates/measures and multiple errors/range coverage without invented probabilities.'],
         criteria=['A1: Fehler0,5/1pp=1, Bandinterpretation1, Energiebedingung1, keine erfundene Wahrscheinlichkeit1.', 'A2: Einzeljahr/Ranggrenze1, Datenstand1, Annahme-/Modellunterschied1, bedingter Nutzen1.', 'A3: konkrete Revision1, neue Inputs/Szenarien1, faire Vergleichsregel1, relevante Zusatzdaten1.'],
         criteria_en=['A1: errors0.5/1pp=1, range1, energy condition1, no invented probability1.', 'A2: one-year/ranking limit1, vintage1, assumption/model1, conditional value1.', 'A3: concrete revision1, new inputs/scenarios1, fair comparison1, additional evidence1.']),
    dict(name='Fall B: Monatsmodell und alter Jahresblick', name_en='Case B: a monthly model and an older annual outlook',
         dossier='Ein anderes fiktives Team prognostiziert mit aktuellen Auftragseingängen die Produktion im nächsten Monat: Punktwert+0,4%, transparentes Szenario−0,2% bei Stornos. Ein sechs Monate altes Strukturmodell prognostizierte Jahreswachstum+1,8% unter normaler Energieversorgung. Jetzt fällt unerwartet ein großer Energielieferant aus; historische Auftragsdaten enthalten noch keinen solchen Ausfall. Das Monatsmodell und das Jahresmodell haben verschiedene Zielgrößen, Horizonte und Datenstände. Datenrevisionen können auch schon gemeldete Produktion verändern.',
         dossier_en='Another fictional team uses current orders to forecast next-month output:+0.4%, with an explicit−0.2% cancellation scenario. A six-month-old structural model projected annual growth+1.8% under normal energy supply. A major energy supplier now unexpectedly fails; historical order data contain no such failure. Models differ in target, horizon and vintage; data revisions can also change previously reported output.',
         prompts=['Vergleiche die beiden Aussagen, ohne Monats- und Jahresraten als dieselbe Größe zu behandeln.', 'Erkläre, weshalb der neue Schock eine Modell-/Datenrevision verlangt und ein kurzfristiger Datensatz nicht auf jedem Horizont überlegen ist.', 'Entwickle ein aktualisiertes Prognoseverfahren mit mindestens einer prüfbaren Annahme und begründe, wie du spätere Fehler fair beurteilst.'],
         prompts_en=['Compare the statements without equating monthly and annual rates.', 'Explain why the new shock requires a model/data update and why high-frequency data are not best at every horizon.', 'Design an updated procedure with a testable assumption and fair assessment of later errors.'],
         solutions=['Monatliche Produktion+0,4 und Jahreswachstum+1,8 sind nicht direkt konkurrierende gleichartige Werte. Szenario−0,2 hängt an Stornos, kein sicheres Intervall. Alte Jahresannahme normale Energie ist jetzt fraglich; aktuelle Information ist ein Vorteil für kurzfristige Wendepunkte, ersetzt strukturelle Langfristfragen nicht.', 'Neue reale Angebotskapazität/Energieverfügbarkeit bricht den bisherigen Zusammenhang Aufträge→Produktion; unlieferbare Aufträge erhöhen nicht automatisch Output. Jahresmodell braucht aktuellen Datenstand/Annahme. Veröffentlichungsvintage, Messrevision und Prognosefehler sind auseinanderzuhalten.', 'Kombiniere aktualisierte Energie-/Kapazitätsdaten mit Aufträgen, Szenarien für Ausfalldauer und Lieferersatz sowie separat datiertem Jahresmodell. Später gleiche Variable/Horizonte/Vintages und revidierte/Erstveröffentlichungswerte transparent vergleichen. Ein Fehler zeigt Grenze, nicht automatisch völlige Nutzlosigkeit.'],
         solutions_en=['Monthly output+0.4 and annual growth+1.8 are not matched rival values.−0.2 is a cancellation scenario, not a guaranteed range. Normal-energy assumptions are now doubtful; fresh data help near-term turns but do not replace structural long-run questions.', 'Capacity/energy loss can break the orders-to-output relation; unfillable orders do not mechanically raise production. The annual model needs updated inputs/assumptions. Publication vintage, measurement revision and forecast error must be separated.', 'Combine updated energy/capacity with orders, outage-duration and substitution scenarios, plus a separately dated annual model. Later compare equal variables, horizons and vintages, distinguishing first and revised observations. Error reveals a limit rather than automatic uselessness.'],
         criteria=['B1: Zielgröße/Horizont1, Datenstand1, Szenario/Band1, kein unzulässiger Zahlenvergleich1.', 'B2: Schockmechanismus1, geänderte Modellannahme1, Kurz-/Langfristgrenze1, Messrevision/Fehler1.', 'B3: konkrete aktualisierte Inputs1, prüfbare Annahme1, faire spätere Fehlerbeurteilung1, bedingter Nutzwert1.'],
         criteria_en=['B1: target/horizon1, vintage1, scenario/range1, no invalid numerical comparison1.', 'B2: shock mechanism1, changed assumption1, horizon limit1, data revision/error1.', 'B3: updated inputs1, testable assumption1, fair later error assessment1, conditional value1.']),
    'Wenn die gesamte Arbeit keine Prognose anhand von Datenstand, Zielhorizont und Annahmen bewertet oder keinerlei sachlich begründete Revision nach neuen Informationen zeigt, sind höchstens14 Punkte erreichbar.',
    'If the whole submission evaluates no forecast through vintage, horizon and assumptions, or gives no reasoned revision after new information, the score is capped at14.')

ECB23='https://www.ecb.europa.eu/press/key/date/2023/html/ecb.sp230925_1~7ad8ef22e2.en.html'
BB22='https://www.bundesbank.de/de/aufgaben/geldpolitik/fragen-und-antworten-zur-inflation-802760'
add('25278ecf', 'Inflationsdossier, gewichtete Preise und echte Deflation unterscheiden', 'Distinguishing an inflation dossier, weighted prices and actual deflation',
    dict(name='Fall A: Historisches Dossier und fiktiver Warenkorb', name_en='Case A: a historical dossier and fictional basket',
         dossier='Datierte eigene Lesehilfe: EZB-Rede „Money and inflation“,25.9.2023 ('+ECB23+'), behandelt Pandemie-Geldwachstum zusammen mit Lieferengpässen, Energieverteuerung und widerstandsfähiger Nachfrage. Gleichzeitiges Geld-/Preiswachstum ist allein kein isolierter Ursachennachweis; die Rede untersucht mögliche Wechselwirkungen. Diese Quelle ist historisch, kein heutiger Messbericht. Daneben ein ausdrücklich unabhängiger fiktiver Jahreswarenkorb: Basis Energie100/übrige breite Konsumgruppe100, Basisgewichte20%/80%. Jahr1:150/100; Jahr2:154,5/103. Gesamtindex=0,2·Energie+0,8·übrige. Haushalt H verwendet feste Basisgewichte50%/50%. Methodischer historischer Hinweis: Bundesbank-FAQ mit2022er-Kontext ('+BB22+') erklärt breite Inflation und durchschnittlichen Warenkorb; damalige Prognosen werden hier nicht als heutige Werte benutzt. Güterqualität und feste Mengen sind im Rechenmodell unverändert.',
         dossier_en='Original dated aid: ECB speech “Money and inflation”,25September2023 ('+ECB23+'), considers pandemic money growth with supply bottlenecks, higher energy costs and resilient demand. Coincident money/price growth alone does not isolate causality; interactions are investigated. This is historical, not a current report. Separately, a fictional annual basket has base energy100/other broad consumption100, fixed base weights20%/80%. Year1:150/100; year2:154.5/103. Total=0.2·energy+0.8·other. Household H has fixed50%/50% base weights. Historical method aid: a Bundesbank FAQ in its2022context ('+BB22+') explains broad inflation and an average basket; old projections are not current values. Model quality and quantities are unchanged.',
         prompts=['Ordne das historische Dossier zeitlich und mehrkausal ein: vergleiche Kosten- und Nachfrageerklärung und nenne trennende Belege.', 'Berechne die beiden allgemeinen Indizes und Jahresraten sowie Hs Indizes. Erkläre Preisniveau, Inflation und Disinflation.', 'Beurteile Kaufkraft und unterschiedliche Belastung sowie Grenzen von Gewichten, Qualität und Kausalnachweis; trenne alle Fiktionen von Quellenbefunden.'],
         prompts_en=['Place the historical dossier in time and compare cost/demand explanations with discriminating evidence.', 'Calculate both general indices/rates and H’s indices; explain price level, inflation and disinflation.', 'Assess purchasing power, exposure and weight/quality/causal limits, separating fiction from source observations.'],
         solutions=['2023-Rede interpretiert die damalige Pandemie-/Energieperiode. Liefer-/Energiekosten können Angebot/Preise drücken bzw erhöhen; tragfähige Nachfrage kann Weitergabe ermöglichen und Geldentwicklung mit beiden verbunden sein. Gleichlauf isoliert keine alleinige Ursache. Zeitfolge/Sektoren, Mengen, Margen und reale Nachfrage liefern trennende Hinweise.', 'Allgemein110 und113,3; Raten10% und3%. H125 und128,75, Raten25% und3%. Sinkende positive Rate heißt Disinflation bei weiter steigendem Niveau, nicht Rückkehr auf100. Gewichtete Summe statt schlichtem Mittel.', 'Ein fester Nominalbetrag verliert Kaufkraft; Hs Basisbelastung ist anders, kein amtlicher VPI und nicht automatisch seine exakten aktuellen Lebenshaltungskosten. Mengen-/Qualitätsänderungen, Ersatzkäufe und tatsächliche Gewichte fehlen. Energieanstieg oder Geldgleichlauf allein beweist keine gesamte Kausalerklärung; historische und fiktive Werte sind klar getrennt.'],
         solutions_en=['The2023 speech interprets the contemporary pandemic/energy period. Supply/energy costs can constrain quantities and raise prices; resilient demand can enable pass-through and monetary developments can relate to both. Coincidence isolates no sole cause. Timing/sectors, volumes, margins and real demand help discriminate.', 'General indices110/113.3, rates10%/3%; H125/128.75, rates25%/3%. Lower positive inflation is disinflation with a still-rising level, not a return to100. Use weighted sums rather than a simple mean.', 'Fixed nominal money loses purchasing power; H has different base exposure, neither official CPI nor exact current living costs. Quantity/quality changes, substitution and actual weights are missing. An energy rise or monetary coincidence alone proves no whole causal explanation; history and fiction remain separate.'],
         criteria=['A1: Historie datieren1, Kostenmechanismus1, Nachfrage/Wechselwirkung1, trennender Beleg1.', 'A2: allgemeine Indizes1, Raten/Disinflation1, H-Indizes1, Gewichtung/Niveau1.', 'A3: Kaufkraft/Belastung1, Modell-/Messgrenze1, Kausalgrenze1, Historie/Fiktion1.'],
         criteria_en=['A1: historical dating1, cost channel1, demand/interaction1, discriminator1.', 'A2: general indices1, rates/disinflation1, H indices1, weights/level1.', 'A3: purchasing power/exposure1, model/measurement limit1, causal limit1, history/fiction1.']),
    dict(name='Fall B: Breite fallende Preise und feste Schulden', name_en='Case B: broadly falling prices with fixed debt',
         dossier='Anderes ausdrücklich fiktives jährliches Dossier: vergleichbarer breiter Preisindex110→108→106, über mehrere große Warengruppen. Nominaleinkommen100 und fällige nominale Schuld50 bleiben zunächst konstant. Realproduktion und Nachfrage sinken, gleichzeitig verbessert eine neue Technik die Produktivität. Welche Ursache wie stark wirkt, ist nicht isoliert gemessen. Gewichte und Qualität werden für die Rechnung konstant gesetzt, müssen bei realer Messung aber geprüft werden. Ein Kommentar nennt dies „nur niedrigere positive Inflation und für alle sicher gut“.',
         dossier_en='Another explicitly fictional annual dossier: comparable broad price index110→108→106 across several major product groups. Nominal income100 and debt due50 initially remain fixed. Real output/demand fall while new technology improves productivity; individual causal contributions are not identified. Weights/quality are fixed for calculation but require checks in actual measurement. A comment calls it “merely lower positive inflation and certainly good for everyone”.',
         prompts=['Berechne die beiden Raten, klassifiziere die Preisentwicklung und erkläre die Messbedingungen.', 'Berechne die Kaufkraft von Einkommen100 und realer Schuld50 in Basiseinheiten bei110 und106. Unterscheide Kaufkraftgewinn und Belastung.', 'Vergleiche Nachfrage-/Produktivitätserklärungen und prüfe mögliche Rückkopplung ohne automatische Krisenbehauptung; korrigiere den Kommentar bedingt.'],
         prompts_en=['Calculate both rates, classify the development and explain measurement conditions.', 'Calculate purchasing power of income100 and real debt50 in base units at110/106, separating purchasing-power gain and burden.', 'Compare demand/productivity explanations and potential feedback without assuming a crisis; assess the comment conditionally.'],
         solutions=['−2/110≈−1,82% und−2/108≈−1,85%; anhaltend breiter Niveaufall ist Deflation, nicht langsamere positive Inflation. Keine einzelne Saisonobstpreisänderung; konstante vergleichbare Gewichte/Qualität sind erforderlich.', 'Einkommen:100/1,10≈90,91→100/1,06≈94,34; reale Schuld50/1,10≈45,45→50/1,06≈47,17. Beide feste Beträge gewinnen reale Kaufkraft; für Schuldner steigt reale Last. Das Schuld/Einkommensverhältnis bleibt bei beiden nominal fix50%, was den realen Schuldwertanstieg nicht widerlegt; spätere Einkommens-/Jobverluste sind möglich.', 'Nachfragerückgang kann Absatz/Produktion drücken und Preisrückgang verstärken; Produktivitätsgewinn kann Kostenpreise senken ohne zwingend Krise. Warten auf günstigere Preise kann Nachfrage weiter mindern, aber Erwartung/Finanzlage muss belegt werden. Nicht jede Deflation ist für alle gut und nicht jede Produktivitätsverbesserung beweist Abwärtsspirale; Mengen-, Einkommens- und zeitliche Belege fehlen.'],
         solutions_en=['−2/110≈−1.82% and−2/108≈−1.85%; persistent broad price decline is deflation, not slower positive inflation. It is not one seasonal-fruit change; comparable weights/quality are needed.', 'Income100/1.10≈90.91→100/1.06≈94.34; real debt50/1.10≈45.45→50/1.06≈47.17. Both fixed sums gain purchasing power, increasing borrowers’ real debt burden. The debt/income ratio remains50% with both nominally fixed, which does not refute the rising real debt value; later income/job losses are possible.', 'Demand contraction can reduce sales/output and reinforce falling prices; productivity can reduce cost prices without necessarily causing crisis. Waiting for lower prices can further weaken demand, but expectations/finances need evidence. Neither universal benefit nor automatic spiral follows; volume, income and timing evidence is missing.'],
         criteria=['B1: zwei negative Raten1, Deflation/Niveau1, Breite/Dauer1, Messbedingung1.', 'B2: Einkommenskaufkraft1, reale Schuldwerte1, Last/Gewinn unterscheiden1, Verhältnis-/Einkommensgrenze1.', 'B3: zwei konkurrierende Mechanismen1, bedingte Rückkopplung1, Kommentarurteil1, nötige trennende Daten1.'],
         criteria_en=['B1: two negative rates1, deflation/level1, breadth/persistence1, measurement1.', 'B2: income purchasing power1, real debt values1, burden/gain1, ratio/income limit1.', 'B3: competing channels1, conditional feedback1, comment assessment1, discriminating data1.']),
    'Wenn in der gesamten Arbeit keine datierte mehrkausale Fallinterpretation gezeigt wird oder die Unterscheidung von Niveau, Rate und breiter Deflation vollständig fehlt oder feste reale Schuld- und Kaufkraftpositionen vollständig verwechselt werden, sind höchstens14 Punkte erreichbar.',
    'If the whole submission gives no dated multicausal interpretation, entirely lacks the distinction between level, rate and broad deflation, or wholly confuses fixed real debt and purchasing-power positions, the score is capped at14.',
    ['ecb2023', 'bundesbank2022'])

add('b2419b68', 'Modellnutzen und reale Grenzen: Nachfrage und Qualifikation', 'Model usefulness and real limits: demand and training',
    dict(name='Fall A: Ein öffentlicher Impuls unter festen Annahmen', name_en='Case A: a public impulse under fixed assumptions',
         dossier='Fiktives Modell einer geschlossenen Wirtschaft ohne Steuern, mit festen Preisen und freier Kapazität: Konsumquote c=0,75, zusätzlicher autonomer Staatsauftrag ΔG=10, ΔY=ΔG/(1−c). Bei dem tatsächlichen diskutierten Bauprojekt werden jedoch40% der ersten Ausgaben importiert, lokale Baukapazität ist voll und eine neue Anlage entsteht erst in zwei Jahren. Das einfache Modell enthält diese Tatsachen nicht. Für die abweichende offene/kapazitätsbeschränkte Wirtschaft ist kein zusätzlicher fertiger Multiplikator gegeben.',
         dossier_en='Fictional closed-economy model with no taxes, fixed prices and spare capacity: consumption share c=0.75, autonomous public order ΔG=10, ΔY=ΔG/(1−c). For the actual classroom construction proposal,40% of initial spending is imported, local capacity is full and a new facility takes two years. The simple model omits these facts; no ready multiplier is supplied for the open/capacity-constrained alternative.',
         prompts=['Berechne das Modellergebnis und erkläre seinen Nachfrage-/Einkommensmechanismus.', 'Prüfe die tatsächlichen Annahmeverletzungen und beurteile das Versprechen „sicher sofort40 zusätzliche Produktion“.', 'Formuliere einen begrenzten sinnvollen Modellgebrauch, eine geeignete Erweiterung und einen entscheidungsrelevanten Datenbedarf.'],
         prompts_en=['Calculate the model result and explain its demand/income mechanism.', 'Check actual assumption failures and assess “certain immediate40 extra output”.', 'Specify a useful limited application, suitable extension and decision-relevant evidence need.'],
         solutions=['Multiplikator4, modellierte ΔY40. Erste autonome Nachfrage10 schafft Einkommen, davon75% Folgekonsum mit weiterer Einkommenserzeugung; geometrischer Zusammenhang nur unter den Annahmen, kein kostenloser fiskalischer Ertrag.', 'Importe lassen Nachfrage abfließen; volle Baukapazität kann Preise/Verdrängung statt reale Mengen erzeugen; Anlagenverzug begrenzt sofortige Wirkung.40 ist daher kein sicherer tatsächlicher Wert; aus40% Importen allein lässt sich ohne weitere Struktur kein vollständiger alternativer Effekt ableiten.', 'Nutze Modell zur Erklärung des Verstärkungsprinzips und als bedingtes Szenario, nicht als Prognosegewissheit. Ergänze Import-/Spar-/Steuerreaktion und Kapazitäts-/Zeitgrenzen. Tatsächliche Lieferketten, Auslastung, Preisreaktion und Auszahlungsplan helfen die Entscheidung bewerten.'],
         solutions_en=['Multiplier4, model ΔY40. Initial demand10 creates income,75% feeds subsequent consumption/income; the geometric chain depends on assumptions and is not free fiscal revenue.', 'Imports leak demand; full construction capacity can raise prices/crowd out activity instead of real volume; facility delays limit immediacy.40 is no certain outcome; import share alone cannot determine a complete alternative effect without more structure.', 'Use the model to explain amplification and a conditional scenario, not forecast certainty. Add import/saving/tax behaviour plus capacity/timing limits. Supply chains, utilisation, prices and payment timing inform evaluation.'],
         criteria=['A1: Multiplikator4=1, ΔY40=1, Mechanismus1, Bedingtheit1.', 'A2: Importgrenze1, Kapazitätsgrenze1, Zeitgrenze1, kein unberechtigter Ersatzwert1.', 'A3: sinnvoller begrenzter Gebrauch1, konkrete Erweiterung1, fachlicher Datenbedarf1, bedingtes Entscheidungsurteil1.'],
         criteria_en=['A1: multiplier4=1, ΔY40=1, mechanism1, conditionality1.', 'A2: imports1, capacity1, timing1, no unjustified substitute result1.', 'A3: useful bounded application1, extension1, evidence1, conditional judgment1.']),
    dict(name='Fall B: Können200 Produkte auch verkauft werden?', name_en='Case B: can200 products actually be sold?',
         dossier='Andere fiktive Maßnahme:20 Personen absolvieren eine zwölfmonatige Ausbildung. Vorgegebene Jahreskapazitätsregel: Jede erfolgreich ausgebildete passend beschäftigte Person kann mit vorhandener geeigneter Anlage10 Produkte zusätzlich herstellen. Anlagen sind nicht vollständig gesichert. Die Quote erfolgreicher Abschlüsse, Matching in passende Stellen und künftige Absatznachfrage sind unbekannt. Ein Politiker verspricht „200 zusätzliche Verkäufe schon nächsten Monat“. Das Kapazitätsmodell enthält weder Preise/Absatz noch Ausbildungsverzug oder Ausfallrisiko.',
         dossier_en='Another fictional intervention trains20 people over twelve months. Supplied annual capacity rule: each successful graduate employed in a matching job with suitable equipment can make10 additional products. Equipment is not fully secured; completion, job matching and future demand are unknown. A politician promises “200 extra sales next month”. The capacity model omits prices/sales, training delay and failure risk.',
         prompts=['Berechne die bedingte jährliche Obergrenze und unterscheide Kapazität, tatsächliche Produktion und Verkauf.', 'Prüfe das Versprechen anhand von Zeitpunkt, Abschlüssen, Anlagen, Matching und Nachfrage.', 'Gib einen sinnvollen bedingten Entscheidungsrahmen mit prüfbarer Variation statt einer behaupteten sicheren Prognose.'],
         prompts_en=['Calculate the conditional annual upper bound and distinguish capacity, production and sales.', 'Assess the promise using timing, completion, equipment, matching and demand.', 'Give a useful conditional decision framework with a testable variation rather than a certain forecast.'],
         solutions=['20·10=200 zusätzliche jährliche Kapazität nur bei allen erfüllten Bedingungen nach Ausbildung. Kapazität ist mögliche Produktion; tatsächliche Produktion braucht Auslastung, Verkäufe Nachfrage. Nicht200 im nächsten Monat.', 'Zwölf Monate verhindern Sofortwirkung; Abbrüche und unpassende Stellen reduzieren passende Beschäftigte; fehlende Anlagen begrenzen Produktion; unzureichender Absatz kann mögliche Menge unverkäuflich machen. Ohne Daten keine sichere Zahl tatsächlicher Jobs/Verkäufe.', 'Etwa bedingt in Stufen finanzieren und Abschlüsse, Anlagenverfügbarkeit sowie Absatz prüfen. Bei16 erfolgreich passend Beschäftigten und ausreichender Anlage läge Kapazitätsobergrenze160, weiter kein garantierter Absatz. Produktivität/Matching/Dauer sind modellierbar; andere begründete Maßnahme oder Verschiebung ist vertretbar.'],
         solutions_en=['20×10=200 additional annual capacity only after training with all conditions met. Capacity is potential output, actual production needs utilisation, and sales need demand. It is not200 next month.', 'Twelve months prevent instant effects; dropouts and mismatch reduce qualified employed people; absent equipment constrains output; inadequate demand can leave capacity unsold. Without evidence, jobs/sales are not certain.', 'For example, fund in stages while monitoring completion, equipment and sales demand. With16 successful matched employees and suitable equipment the capacity ceiling is160, still not guaranteed sales. Productivity/matching/duration can be modelled; another reasoned choice or delay is valid.'],
         criteria=['B1:200 bedingt/jährlich1, Kapazität1, Produktion1, Absatz1.', 'B2: Zeit/Abschlüsse1, Anlagen1, Matching1, Nachfrage/Gewissheitsgrenze1.', 'B3: bedingter Rahmen1,160-Variation oder gleichwertige prüfbare Variation1, relevante Daten1, begrenzter Modellnutzen1.'],
         criteria_en=['B1: conditional annual200=1, capacity1, production1, sales1.', 'B2: time/completion1, equipment1, matching1, demand/certainty1.', 'B3: conditional framework1,160 or equivalent testable variation1, evidence1, limited model usefulness1.']),
    'Wenn die gesamte Arbeit keinen Modellmechanismus mit seinen Annahmen erläutert oder keinerlei konkrete Verletzung einer entscheidungsrelevanten Annahme und ihre Folgen begründet, sind höchstens14 Punkte erreichbar.',
    'If the whole submission explains no model mechanism with its assumptions, or justifies no concrete failure of a decision-relevant assumption and its consequences, the score is capped at14.')

